quests[84740] = { id = 84740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brücke ins Nirgendwo", description = "Geht Ihr zu den Dünen? Ich suche meine Schwester Shahata. Ich weiß nicht, ob sie noch am Leben ist, aber ich muss sie finden.\n\nDer einzige Startpunkt, der mir einfällt, ist unser Dorf. K'aresh hat sich sehr verändert. Ich benötige Orientierungspunkte. Irgendetwas, an dem ich mich orientieren kann.\n\nNehmt diesen Echovermesser. Er findet Spuren aus der Vergangenheit. Hoffentlich genug für mich, um uns zu lenken.", sourceObjective = "Helft Om'fennad mit dem Echovermesser, sich zu orientieren.", completion = "Danke, {name}. Ich glaube, jetzt weiß ich, wo wir lang müssen. Seht Ihr, wie belebt es hier einmal war? Schwer vorstellbar, dass Shahata hier so lange überlebt hat... Nein. Wir werden sie finden. Das müssen wir.", sourceObjectiveStatus = "unverified-source-field" }
quests[84741] = { id = 84741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren im Sand", description = "Langsam kommt mir die Umgebung bekannter vor. Ich glaube, ich weiß jetzt, wo es zurück zu meinem Dorf geht.\n\nIch sollte Euch aber sagen... Ich suche nicht nur meine Schwester. Unsere Mutter starb, als ich in der Stadt studiert habe. Shahata hat sie in meiner Abwesenheit unter ihrem Lieblingsbaum begraben. Ich hatte geschworen, nach Hause zu kommen, um den Bestattungsritus durchzuführen, habe es aber nicht rechtzeitig geschafft.\n\nIch bin meinem Eid viel zu lange nicht nachgekommen. Ich bin es meiner Mutter schuldig, es zumindest nun zu versuchen. Kommt. Durchsuchen wir das Dorf.", sourceObjective = "Folgt Om'fennad zu seinem Dorf.", progress = "Das kann doch nicht sein! Irgendetwas muss doch noch da sein.", completion = "Keine Ahnung, was ich erwartet hatte. Sie hat recht. Ich habe meinen Eid gebrochen und nun gibt es das Dorf nicht mehr... Aber sie ist immer noch hier.\n\nSollte sie etwas haben, das unserer Mutter gehörte, dann könnte der Vermesser es zum Grab verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84755] = { id = 84755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Spielzeug", description = "Maru hat herausgefunden, dass jetzt eines ihrer Spielzeuge fehlt!\n\nKönnte das im Zusammenhang mit den verschwundenen Spielzeugen ihrer Freunde stehen, die Ihr schon gesucht habt?", sourceObjective = "Sprecht mit Maru.", completion = "Neeein! Mein Spielzeug ist verschwunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[84756] = { id = 84756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spielzeugdieb", description = "Mein Szpielszeug! Esz wurde gesztohlen!\n\nWir müszen herauszfinden, wer der Gauner iszt, bevor er wieder szuszlägt!", sourceObjective = "Finde den Spielzeugdieb.", progress = "Habszt Ihr mein Szpielszeug gefundszen?", completion = "Jippie! Ihr habszt ALLE Szpielszeuge gefundszen! Wie hat der grosze Hundszi szich szo viele gesznappt?\n\nIch musz szauen, ob noch mehr von meinszen Szpielszeugen in dem Haufen szind...\n\nDanke für die Hilfsze.", sourceObjectiveStatus = "unverified-source-field" }
quests[84759] = { id = 84759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unschöne Begegnung unterm Sternenzelt", description = "Ich hatte mir schon meine Worte für das Wiedersehen mit meinem Bruder zurechtgelegt. Aber dann habe ich nicht mehr geglaubt, dass ich...\n\nEr war die ganze Zeit fort und nun möchte er Erbstücke? Ich habe das Grab unserer Mutter neben ihrem Lieblingsbaum ausgehoben. Allein. Er hätte damals zurückkommen sollen! Ich habe jetzt keine Zeit, sein Gewissen zu beruhigen.\n\nFalls Ihr zwei unbedingt reden wollt, seid wenigstens so anständig, es nicht in aller Öffentlichkeit zu tun. Kommt in mein Lager. Dort können wir reden.", sourceObjective = "Trefft Shahata in ihrem Lager.", completion = "Ich hätte nicht erwartet, Fennad noch einmal zu sehen. Er kommt etwas zu spät, um bei den Beerdigungsriten unserer Mutter zu helfen. Der Baum ist mit dem Grab verschwunden. Und jetzt bittet er um Gefallen?", sourceObjectiveStatus = "unverified-source-field" }
quests[84760] = { id = 84760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine freundliche Warnung", description = "Vor dem Verschlingen waren die Sufaadi Priester. Es gab Anstands- und Wohltätigskeitsbräuche. Aber sie sind mit dem Rest von K'aresh verschwunden. Sollten die Ödnisbewohner denken, ich würde mich nicht rächen, würden sie nie aufhören, mich ins Visier zu nehmen.\n\nIch denke, Ihr versteht den Wert einer Machtdemonstration. Tötet ihre Anführer zur Warnung der anderen.", sourceObjective = "Tötet Seelenbinder Sabeel und Duellantin Xaheen.", completion = "Hoffentlich reicht das, um sie abzuschrecken. Zumindest für eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[84761] = { id = 84761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für den Hausfriedensbruch", description = "Fennad hat sich einen schlechten Zeitpunkt ausgesucht, um mich um Hilfe zu bitten. Ich reise ab, sobald ich mir meine Vorräte von den Sufaadi wiederbeschafft habe.\n\nSie haben mich unterwegs überfallen und hätten mich auch getötet, hätte Ruya mich nicht fortgeschleppt. Ich habe sie bis nach Sufaad verfolgt, aber es sind zu viele für mich allein.\n\nWenn Ihr mir helft, meine Vorräte zurückzubekommen, schaue ich, was ich für Fennad tun kann.", sourceObjective = "Bergt Shahatas gestohlene Vorräte.", progress = "Hoffentlich haben sie nicht bereits alles verbraucht.", completion = "Mehr habt Ihr nicht gefunden? Sie haben keine Zeit damit verloren, sich an meinen Vorräten gütlich zu tun. Aber immerhin ist noch ein wenig da.", sourceObjectiveStatus = "unverified-source-field" }
quests[84762] = { id = 84762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An unseren Worten werden wir gemessen", description = "Ich hatte eine von unserer Mutter mit Perlen besetzte Halskette. Die Sufaadi haben sie mir bei dem Überfall gestohlen. Es gibt nur noch wenige Sachen aus dem alten K'aresh. Sollten die Sufaadi sie nicht verkauft haben, müsste sie bei den anderen Wertsachen sein.\n\nIch wollte sie eigentlich zurücklassen. Man sollte sein Leben nicht aus Sentimentalität aufs Spiel setzen. Aber Ihr habt Euer Wort gehalten. Und das ist mehr, als ich von meinem Bruder sagen kann. Helft mir, die Halskette wiederzubeschaffen, dann gehört sie Euch.", sourceObjective = "Helft Shahata, die Halskette ihrer Mutter wiederzubeschaffen.", progress = "Was ist geschehen? Wo ist Fennad?", completion = "Alles weg. Vorräte, die monatelang gereicht hätten, sind in Flammen aufgegangen. Falls Fennad nicht bereits tot ist, wird er es bald sein. Die Sufaadi werden keine Nachsicht zeigen. Vor allem nicht nach dem, was wir getan haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84765] = { id = 84765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Eiden und Schwüren", description = "In Tazavesh habe ich die ganze Zeit an meine Heimkehr gedacht. Doch nun sorgt sie nur für noch mehr Trauer. Selbst wenn der Vermesser nicht beschädigt wäre, hätte ich nichts, um zum Grab unserer Mutter zu finden.\n\n<Om'fennad schaut sich in der Höhle um.>\n\nSeht Ihr diese Zeichen? Dies war ein Schrein des Austauschs. Wahrscheinlich ein passender Ort, um sich endgültig zu verabschieden. Würdet Ihr mir noch ein letztes Mal helfen? Nichts Gefährliches. Zündet nur ein wenig Weihrauch an.", sourceObjective = "Helft Om'fennad und Shahata, ihrer Mutter eine letzte Ehre zu erweisen.", completion = "Nach all dieser Zeit dachte ich, es würde sich anders anfühlen, wenn wir den Eid erfüllten.\n\nVielleicht ist nun die Zeit gekommen, um nicht mehr zurückzudenken. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[84767] = { id = 84767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verkohlte Feierkiste", description = "<Die Kiste ist vom Feuer ganz verkohlt, aber das Innere sollte nichts abbekommen haben. Alyx würde sich über die Vorräte freuen.>", sourceObjective = "Bringt die verkohlte Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84773] = { id = 84773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallisierte Feierkiste", description = "<Die Kiste ist kristallisiert und lässt sich kaum aufstemmen. Alyx würde sich über die Vorräte freuen.>", sourceObjective = "Bringt die kristallisierte Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84776] = { id = 84776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Tiefe", description = "In den Tiefen dieses Landes verbergen sich viele Schätze.\n\nVielleicht sind einige ja nützlich für Euch.", sourceObjective = "Schließt 5 Tiefen in Khaz Algar ab.", progress = "Hütet Euch vor den Gefahren der Tiefen.", completion = "Ihr habt überlebt! Großartig!", sourceObjectiveStatus = "unverified-source-field" }
quests[84779] = { id = 84779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Der Schachzug der Klinge", description = "Auch wenn sie damals nur eine Klinge geringer Kraft war, blieb Xal'atath nicht tatenlos. Im Nachspiel zur Invasion der Legion brachen die Spannungen zwischen der Horde und der Allianz zum Vierten Krieg aus.\n\nXal'atath machte sich die vielen verschiedenen Kräfte, die am Krieg teilhatten, in einem Schachzug zur Wiederherstellung ihrer Macht zum Vorteil.", sourceObjective = "Hört Lehrensucher Cho zu, um von Xal'ataths Geschichte während des Vierten Kriegs zu erfahren.", completion = "Ich glaube, die Informationen, die meine Lehrensucherkollegen und ich gefunden haben, sind vollkommen neu. Was ihre Bedeutung betrifft, bin ich mir noch unsicher, aber vielleicht könnt Ihr das ja entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84781] = { id = 84781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Geheimnisse", sourceObjective = "Wie ich sehe, gehört Ihr ebenfalls zu den Geheimnisjägern! Mir wurde aufgetragen, Euch das hier zu geben. Viel Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[84782] = { id = 84782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Die Vergangenheit der Klinge", description = "Vor vielen Jahren hat eine Steintafel aus dem Sturmsangtal ihren Weg in meine Bibliothek gefunden.\n\nEs hat Jahre gedauert, die Chiffren zu entschlüsseln und die Fragmente der gravierten Runen zu übersetzen.\n\nIch erzähle Euch, was wir zusammentragen konnten. Eine Geschichte von noch mehr Verrat...", sourceObjective = "Hört Lehrensucher Cho zu, um von Xal'ataths Geschichte in Ny'alotha zu erfahren.", completion = "Ihr seid auserwählt, so bemitleidenswert Ihr auch seid. Ihr solltet dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[84784] = { id = 84784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Die Erzfeinde der Klinge", description = "Lord N'Zoth bedarf nun seiner Gebrüder, um Xal'ataths Niederlage zu gewährleisten. Ihr wurdet auserwählt, ihre Ankunft in die Wege zu leiten.\n\nIhr wisst, was zu tun ist.", sourceObjective = "Aktiviert die 3 Ritualobeliske, um Yogg-Saron, C'Thun und Y'Shaarj zu beschwören.", progress = "Verschwendet nicht die Zeit von Lord N'Zoth.", completion = "Ich habe keine Zweifel, dass Lord N'Zoth diese Xal'atath auch ohne die Hilfe seiner Gebrüder vernichten könnte, hätte sie uns nicht derartig infiltriert.", sourceObjectiveStatus = "unverified-source-field" }
quests[84787] = { id = 84787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abfluss" }
quests[84788] = { id = 84788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißraketenhotdogs" }
quests[84789] = { id = 84789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Der Untergang der Klinge", description = "Sie sind bereit.\n\nDie Lords halten Xal'atath in der Feste. Ihr seid der Kiesel, der ihre Lawine der Macht ins Rollen bringen wird. Bereitet Xal'atath ein Ende.\n\nNa los. Geht zu ihnen.", sourceObjective = "Konfrontiert Xal'atath.", completion = "Welche Bedeutung hatten die letzten Worte von Xal'atath an N'Zoth? Sah sie ihre zukünftige Zusammenarbeit voraus?\n\nWar das von Anfang an ihr Plan?", sourceObjectiveStatus = "unverified-source-field" }
quests[84791] = { id = 84791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißraketenburger" }
quests[84820] = { id = 84820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch Eid und Blut", description = "Nach dem Verschlingen hätte ich nicht gedacht, Fennad noch einmal wiederzusehen. Zuerst war es leichter, wütend auf ihn zu sein, weil er uns verlassen hatte als zu trauern. Dann war es leichter, alles zu verdrängen und mich nur darauf zu konzentrieren, den nächsten Tag zu überstehen. Ihn wiederzusehen hat alles wieder in mir aufgewühlt.\n\nEidbrecher... Er hat seinen Schwur, heimzukehren, zwar gebrochen, aber die Familie ist der erste Schwur, in den wir geboren werden. Was wäre ich, wenn ich ihn jetzt im Stich lassen würde?\n\nEr ist mein Bruder. An mich gebunden durch Eid und Blut. Ich werde ihn nicht den Sufaadi überlassen.", sourceObjective = "Befreit Om'fennad.", completion = "Ich habe nicht unbedingt damit gerechnet, dass sie kommen würde, um mich zu retten. Schon gleich gar nicht auf diese Weise. Aber nun ist der Vermesser beschädigt und Shahatas Vorräte sind in Flammen aufgegangen. Vielleicht wäre ich besser nicht heimgekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84821] = { id = 84821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biologisches Stechpuppier", description = "Habt Sporen verdient, jetzt Zeit für nutzen!\n\nSchleime laufen weg mit Ritterattrappen, aber damit nur bewegliche Ziele sein. Gut für Übung!\n\nIhr auf edles Maulwurfross am Tor steigen, mit Lanze zielen und Schleim umreiten.\n\nWichtige Fähigkeit für jeden Ritter, ja.", sourceObjective = "Trefft mit einer Lanze von Schleimen getragene Zielattrappen vom Maulwurfrücken aus.", progress = "Nehmt Euch vor Großen in Acht! Treten stark!", completion = "Ha! Lanze die Beulen einfach mögen, ich sie von hier platzen gehört.\n\nIhr guter Ritter werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84822] = { id = 84822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Iskaara", description = "Bringen wir die Kinder zurück nach Iskaara, ja?\n\nIch sehe Euch dort.", sourceObjective = "Trefft Euch mit Hemet Nesingwary in Iskaara.", completion = "Ah, schon besser. Alle sind nun wohlbehalten heimgekehrt. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[84826] = { id = 84826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Biokuppel: Rhovan", description = "Ich werde nicht versuchen, unsere Taten zu rechtfertigen. Ich werde diese Verantwortung für den Rest meines Lebens tragen. Alleria wird schon irgendwann verstehen, dass sie notwendig waren. Wenn sie die Macht des alles Verschlingenden erkennt, wird sie es verstehen.\n\nWir benötigen noch mindestens zwei weitere Reshiibänder, um Dimensius standhalten zu können. Meine Freundin Om'bera besitzt eines. Sie arbeitet in der Biokuppel: Rhovan auf der Nachbarinsel. Holen wir sie auf unsere Seite.", sourceObjective = "Trefft den Raumgänger in der Biokuppel: Rhovan.", completion = "Die Kuppel ist zerstört und Om'bera könnte in Gefahr sein! Dort drinnen sehe ich die Plünderer aus der Ödnis von K'aresh.\n\nOm'bera könnte noch am Leben sein. Wir müssen sie finden. Und ihr Reshiiband.", sourceObjectiveStatus = "unverified-source-field" }
quests[84827] = { id = 84827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zertrümmerte Kuppel", description = "Die Biokuppel: Rhovan wurde von einem herabstürzenden Klumpen Leerenglas vollständig zertrümmert und ihre Wärter wurden versprengt. Sie sind zurückgekommen, um möglichst viel an Ausrüstung, Pflanzen und Tieren zu retten, bevor sie von der Ödnis verschlungen werden.\n\nSucht in der Ruine nach Hinweisen auf Om'beras Schicksal. Wir brauchen ihr Reshiiband. Om'resh und ich suchen den Einschlagkrater ab.", sourceObjective = "Sucht in der Biokuppel: Rhovan nach Om'bera.", progress = "Ist Om'bera vielleicht noch irgendwo in den Trümmern?", completion = "Die Ödnisbewohner haben Om'bera getötet und ihr ihr Reshiiband abgenommen. Diese gefallenen Orakel behelligen die Mitglieder des Geflechts bereits seit dem Verschlingerkrieg. Das ist ein schwarzer Tag.", sourceObjectiveStatus = "unverified-source-field" }
quests[84831] = { id = 84831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befall von Rhovan", description = "Als der Meteor einschlug, versuchte ich mit Om'bera möglichst viel zu retten. Aber ohne den Schutz der Kuppel dauerte es nicht lange, bis wir von Plünderern aus den Großen Dunklen Weiten bedrängt wurden. Bei unserer Flucht wurden wir getrennt.\n\nDiese Kreaturen stammen nicht aus K'aresh und hassen die stabilen Biome, die wir erschaffen wollten. Wir müssen diese invasiven Kreaturen beseitigen, um an unsere Ausrüstung und zu Om'bera zu gelangen.", sourceObjective = "Tötet 10 invasive Kreaturen in der Biokuppel: Rhovan.", progress = "Dies war einst eine blühende Biokuppel des Bundes. Wir forschten an der Wiederherstellung von K'aresh.", completion = "Vielen Dank. Diese Kreaturen hätten uns ohne Euch bald überwältigt.\n\nUnfassbar, dass sie ohne den Schutz der Kuppel überleben können, ohne genauso wie die K'areshi in Energie verwandelt zu werden. Ich frage mich, ob diese Widerstandskraft auf die wenigen einheimischen Spezies in unseren Kuppeln übertragen werden könnte?", sourceObjectiveStatus = "unverified-source-field" }
quests[84834] = { id = 84834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmklüfte", description = "Die Ödnisbewohner waren einst die Orakel der Weltenseele von K'aresh. Sie waren äußerst stolz auf ihre Eide und taten das sehr lautstark kund. Doch nun plündern sie die Ruinen wie die Tiere. Selbst Ratten sind nützlich.\n\nSammelt Leerenkluftessenzen für mich. Ich habe da so eine Idee, wie wir die gefallenen Orakel auf unsere Seite ziehen könnten.", sourceObjective = "Bringt 6 Leerenkluftessenzen zu Xal'atath auf den Sturmfeldern.", progress = "Viele Bewohner der Leere dürsten unersättlich nach Energie. Sie umschwärmen Taschen verdichteter Energien wie Motten das Licht.", completion = "Gut gemacht, Champion. Damit locken wir unsere Beute hervor.", sourceObjectiveStatus = "unverified-source-field" }
quests[84835] = { id = 84835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versunkener Hort" }
quests[84836] = { id = 84836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schauderhöhle" }
quests[84838] = { id = 84838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinde der Feinde", description = "Die Ödnisbewohner haben in den Ruinen des alten K'aresh ihr Lager aufgeschlagen. Es bietet Zuflucht vor den gefräßigen Bestien der Leere, die die Ödnis von K'aresh durchstreifen. Es ist ein Bollwerk gegen Fremdlinge.\n\nSollte ein feindliches Wesen in ihr Lager eindringen, könntet Ihr es bezwingen. Dadurch würdet Ihr ihren Respekt erlangen. Bringt die von Euch gesammelte Leerenenergie in die Turmruine nördlich von hier. Seid auf alles gefasst!", sourceObjective = "Platziert die verdichtete Leerenenergie im Castigar.", completion = "Dimensius hat K'aresh zerstört. Hier in der Ödnis des gnadenlosen K'aresh lassen wir allen Strafe zuteil werden, die ihn im Stich gelassen haben. Ihr sagt, unsere Eide würden sich gleichen? Lasst uns reden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84848] = { id = 84848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor der Leere", description = "Ihr habt die Ödnisbewohner durch Euren Mut zur Gewalt beeindruckt, Champion. Sehr gut. Nun lasst mich meine Arbeit tun.\n\nIch weiß, was diese einstigen Orakel möchten. Sie träumen davon, noch einmal K'areshs Lied zu hören. Ich muss sie davon überzeugen, dass dies möglich sei, und dann ihr Verlangen ausnutzen. Wir werden bald unsere Armee haben, und ein weiteres Reshiiband.\n\nAber zuerst sollten wir den Tabiqaritualdolch zurückbringen.", sourceObjective = "Überredet die Seelenschreiberin dazu, sich mit Euch zu verbünden.", completion = "Wir würden mit Freuden in den Krieg gegen die Schattenwache ziehen, aber ich kann dieses Reshiiband keinem anvertrauen, dem ich nicht traue.\n\nRache kann man leicht versprechen. Aber das Vertrauen der Ödnisbewohner ist schwer zu gewinnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84850] = { id = 84850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlangenzorn" }
quests[84851] = { id = 84851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wellen der Gier" }
quests[84852] = { id = 84852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermächtnis der Vrykul" }
quests[84855] = { id = 84855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totenstille", description = "Dimensius' Macht ist so groß, dass seine Aura selbst dann noch jede sterbliche Existenz schwächt, wenn sie vernichtet wurde. Deshalb wurden die K'areshi in Energiewesen verwandelt. Nur so konnten sie seine Gegenwart überleben.\n\nIch hatte gehofft, meine Späher würden einen sicheren Weg für Euch und Eure Kameraden in die Manaschmiede ausfindig machen. Raz'ida, Lo'shah und Yanhal hätten eigentlich bereits hier sein sollen. Bitte sucht sie für mich. Ihre Informationen sind entscheidend für unseren Kampf gegen den alles Verschlingenden.", sourceObjective = "Sucht die Späher bei der Zo'Shuulwarte.", completion = "Raz'ida war eine Agentin der Schattenwache? Ich habe ihr tausende Jahre lang vertraut. Warum hat sie mir die Treue gebrochen?\n\nWenn sie zum Treuebruch bewegt werden konnte, dann kann dies auch auf jeden anderen Agenten des Bundes zutreffen. Wir müssen unbedingt etwas über ihre Basis herausfinden und dabei können wir uns nur auf uns vier verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84856] = { id = 84856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo sich die Leere sammelt", description = "Mit dem Reshiiband des Raumgängers kann ich Euer Fleisch in Energie umwandeln. Das tut kaum weh.\n\nDann könnt Ihr Dimensius' Aura durchqueren, ohne getötet zu werden. Dort könnt Ihr einen Zugang zur Manaschmiede suchen. Ihr werdet als Energiewesen durch den ungebundenen Raum reisen und so von der Schattenwache ignoriert werden. Von den Leerenbestien allerdings... solltet Ihr Euch fernhalten, wenn Ihr nicht verschlungen werden wollt.\n\nSprecht mich an, wenn Ihr so weit seid. Die Zeit drängt.", sourceObjective = "Durchsucht mit Xal'ataths Hilfe im ungebundenen Raum den Schattenpunkt.", completion = "Damit habt Ihr gelernt, was ich bereits wusste. \n\nDimensius ist eine schreckliche Bedrohung. Wenn wir überleben wollen, {name}, müssen wir zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84857] = { id = 84857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Biokuppel: Primus", description = "Xal'atath hat recht. Wir benötigen mehr als mein eines Reshiiband, um eine Streitmacht zu Dimensius zu führen.\n\nSüdlich von hier steht eine Biokuppel. Dort hält sich die Gründerin des Bundes auf, um ihren Betrieb zu beaufsichtigen. Sie hat die Kuppeln dem Konsortium abgekauft und behauptet, sie wären der Schlüssel zur Wiederherstellung K'areshs. Ich bin allerdings skeptisch, dass jetzt noch irgendwas vor Dimensius sicher ist.\n\nSie gehörte einst dem Geflecht an und besitzt ein Reshiiband. Sie wird es uns bestimmt ausleihen.", sourceObjective = "Trefft den Raumgänger in der Biokuppel: Primus.", completion = "Die Schattenwache hat die Biokuppel angegriffen. Sie muss es auf die gewaltigen Mengen dort gespeicherter Energie abgesehen haben, die benötigt wird, um die empfindliche Kuppel vor der Leere K'areshs zu schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84858] = { id = 84858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Systemneustart", description = "Nur mein Reshiiband verhindert, dass diese Kuppel und deren Systeme kollabieren.\n\nDer Bau dieser Biokuppel hat mich zu viel Geld gekostet, als dass ich die Schattenwache sie einfach zerstören lasse. Sie haben bereits diverse Steuerungskonsolen zerstört und einen kompletten Zusammenbruch des Ökosystems riskiert.\n\nFindet Ingenieur Om'loof und helft ihm, unser Lebenserhaltungssystem neu zu starten, während ich den Rest der Kuppel kontrolliere.", sourceObjective = "Helft Ingenieur Om'loof in der Biokuppel: Primus.", progress = "Diese Biokuppel bricht zusammen, wenn das Lebenserhaltungssystem ausfällt. Wir müssen es stabilisieren!", completion = "Das Lebenserhaltungssystem läuft zwar wieder, aber Ihr könnt Euch noch nicht auf Euren Lorbeeren ausruhen. Das war lediglich das erste zahlreicher Probleme, die diese Biokuppel plagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84859] = { id = 84859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schadensbericht 101", description = "Wie Ingenieur Om'loof habe auch ich mehrere angesehene, hervorragend ausgebildete und teure Unternehmensberater vom Kartell Om eingestellt. Zwei von ihnen haben sich noch nicht gemeldet. Sind sie tot oder lediglich mal wieder abgelenkt?\n\nFindet Botaniker Om'nittar und Schildtechniker Om'door. Besorgt mir ihre Schadensberichte. Ich muss wissen, ob meine Kuppel bei dem Angriff längerfristig beschädigt wurde.", sourceObjective = "Findet Botaniker Om'nittar und Schildtechniker Om'door und bringt ihre Berichte zu Ve'nari.", progress = "Ich heuere die Besten der Besten an. Om'nittar und Om'door werden die Informationen, die ich brauche, mit Sicherheit haben.", completion = "Sind sie am Leben? Sehr gut. Sollten sie es noch mal vergessen, sich zu melden, wird dem nicht mehr so sein.\n\n<Ve'nari überfliegt die Berichte.>\n\nAnscheinend ist der Schaden im Großteil der Anlage minimal, sofern überhaupt vorhanden. Die Saboteure der Schattenwache waren vor allem darauf aus, unsere Energiereserven in die Außenrohre zu leiten. Das Lebenserhaltungs- sowie die Sekundärsysteme haben sie in Ruhe gelassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84860] = { id = 84860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Biostabilisierung", description = "Der Angriff der Schattenwache hat diese Kuppel in Chaos und Unordnung versetzt. Diverse Steuerungskonsolen sind runtergefahren, und meine Berater sind damit alle gefordert, ihre zugeteilten Biome und Systeme wieder hochzufahren.\n\nUnd da kommt Ihr ins Spiel, {name}. Die Aufgabe ist zwar leicht, aber von entscheidender Bedeutung. Findet die deaktivierten Konsolen und startet sie neu.", sourceObjective = "Aktiviert die ausgeschalteten Steuerungskonsolen in der Biokuppel: Primus.", progress = "Laufen die Konsolen wieder? Nein? Dann schaltet sie ein!", completion = "Gute Arbeit, {name}.\n\nDas Kuppelinnere ist damit wieder stabil. Alle Systeme der Biokuppel funktionieren. Meine Investition in die Biokuppeln wird weiterhin Dividende abwerfen. Es sei denn, die Schattenwache greift erneut an.", sourceObjectiveStatus = "unverified-source-field" }
quests[84861] = { id = 84861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist unsere Kuppel!", description = "Wir haben die Saboteure zwar aus der Kuppel vertrieben und deren Systeme repariert, aber das heißt noch lange nicht, dass die Schattenwache meine Kuppel jetzt in Frieden lassen wird. Sie verstecken sich immer noch in der Umgebung und versuchen, an die gewaltige Menge kostbarer Energie zu gelangen, die zum Betrieb der Biokuppel vonnöten ist.\n\nBitte schlagt sie zurück. Dann ist dieser Angriff vielleicht endlich vorbei.", sourceObjective = "Tötet 7 Schattenwachen in der Umgebung der Biokuppel: Primus.", progress = "Habt Ihr sie alle erwischt? Oder verstecken sich immer noch Schattenwachen in der Umgebung und fügen meiner Kuppel Schaden zu?", completion = "Sehr gut. Das verschafft uns genug Zeit, um die Kuppel zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[84862] = { id = 84862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Leerenbündnis", description = "Wir können Euch nicht ewig in der Umgebung dieser Kuppel patrouillieren lassen, wie die Stadtwache dies zur Abwehr von Angreifern tut. Wir benötigen eine dauerhafte Lösung, damit wir unsere edle Mission fortführen können.\n\nNehmt diese Kristalle. Sie wurden auf die Verteidigungsmagie der Biokuppel abgestimmt. Platziert sie an strategischen Punkten in der Umgebung, um die magische Verteidigung zu verstärken.\n\nWas? Das ist diesmal kein Trick. Wenn die Kuppel explodiert, werde ich Dimensius niemals vernichten können.", sourceObjective = "Platziert 4 Xal'atath-Verteidigungen in der Umgebung der Biokuppel: Primus.", progress = "Habt Ihr die Kristalle platziert, die ich Euch gegeben habe? Ve'nari wird ihr Band erst hergeben, wenn die Kuppel gesichert ist.", completion = "Damit sollte die Kuppel gesichert sein. Aber wird Ve'nari noch mehr von uns verlangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[84863] = { id = 84863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenmaßnahmen", description = "Ich kann mein Reshiiband noch nicht abgeben, {name}. Nicht, solange die Schattenwache meine Biokuppel von ihrem Lager in den Gezackten Gipfeln aus weiter angreift. Greift sie dort an! Wenn Ihr ihre Truppen dezimiert, werden sie diesen Angriff beenden.\n\nNehmt Raumgängers Lehrling Alleria mit. Sie sieht aus, als könnte sie gut kämpfen. Außerdem erdolcht sie die Vorbotin mit Blicken und ich habe keine Zeit, die Streitschlichterin zu spielen.", sourceObjective = "Tötet 12 Schattenwachen in den Gezackten Gipfeln.", progress = "Die Schattenwache greift noch immer an. Habt Ihr sie schon dezimiert?", completion = "Gute Arbeit, {name}. Das sollte Ve'nari zufriedenstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84864] = { id = 84864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre dunkle Seite", description = "Eine Astralenarmee ist auf ihre Energiesauger angewiesen. Unterbrecht die Energiezufuhr, indem Ihr ihren Sogturm zerstört, dann wird die Armee sich zurückziehen. Das ist eine der Schwächen als Schergen. Normalerweise würde ich ja für mich behalten, wie man sie bezwingen kann, aber sie haben mich verraten und müssen dafür mit den Konsequenzen leben.\n\nDer Sauger besitzt eine Steuerungskonsole, deren Überladung das System kollabieren lässt. Er wird von einer Leerenbarriere geschützt. Alleria kann sie für Euch beseitigen.", sourceObjective = "Zerstört den Astralen Sog in den Gezackten Gipfeln.", progress = "Nun ist die Schattenwache zum Rückzug gezwungen.", completion = "Ich habe so das Gefühl, das der Raumgänger und Ve'nari mir etwas verheimlichen. Irgendein Geheimnis aus dem Verschlingerkrieg, das sie mir vorenthalten wollen. Xal'atath nutzt meine Zweifel aus, um mich zu manipulieren.\n\nBezwingen wir die Schattenwache, danach können wir die Wahrheit ans Licht bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84865] = { id = 84865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teilen und herrschen", description = "Von allen Kriegsgütern sind die Soldaten am entbehrlichsten. Ich habe genug in die Vernichtung entsandt, um das zu wissen. Wenn wir diese Kuppel für Ve'nari sichern und ihr Reshiiband bekommen wollen, sollten wir ihre Kanonen zerstören.\n\nDie Kanonen sind locker das Leben all ihrer Soldaten wert. Zerstört sie, dann werden ihre Kommandanten zum Rückzug blasen. Die meisten Feldkommandanten würden das zwar niemals zugeben, da es die Moral mindert, aber Ihr wirkt wie jemand, der unangenehme Wahrheiten aushalten kann.", sourceObjective = "Zerstört 3 Kanonen der Schattenwache in den Gezackten Gipfeln.", progress = "Die Zerstörung der Kanonen wird die Schattenwache zum Rückzug zwingen. Aber ich würde nicht auf Xal'ataths Meinung bezüglich Moralvorstellungen hören.", completion = "Ohne ihre Kanonen sind die Angriffe der Schattenwache auf die Biokuppel zum Scheitern verurteilt. Dann braucht Ve'nari ihr Reshiiband nicht mehr.\n\nAllerdings bereitet mir unser Plan immer größere Sorgen. Die Geheimnisse... dieses Bündnis mit Xal'atath. Ich befürchte, der Raumgänger hat vor tausenden Jahren einen Fehler begangen, der uns einholen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[84866] = { id = 84866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherheit erkaufen", description = "Ich muss mich auf die Mission konzentrieren. Unabhängig von meinen Zweifeln an unseren Kameraden stellt die Schattenwache eine Plage dar. Wir sollten ihren Schattenoffizier töten, damit sie nicht so leicht wieder zu der Biokuppel: Primus zurückkehren können. Ve'nari würde uns dann ihr Reshiiband leihen und wir könnten herausfinden, ob ich damit richtig lag, dem Raumgänger zu vertrauen.\n\nIch werde nicht zulassen, dass meine Zweifel meine Kampfkraft schmälern, {name}. Ihr könnt darauf zählen, dass ich die Anhänger von Dimensius jagen werde.", sourceObjective = "Tötet Schattenoffizier Lakheesh.", completion = "Nachdem die erforderliche Gewalt eingesetzt wurde, können wir drei uns unterhalten. Ihr habt recht, Alleria. Euch wurden große Geheimnisse vorenthalten. Geheimnisse, die ich nicht verraten durfte, die Ihr aber schon vor vielen Jahren hättet erfahren sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84867] = { id = 84867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirschende Pirscher", description = "Ich habe die Saat gesät, aber die Seelenschreiberin zögert immer noch. Ihre Tochter Narathe ist da empfänglicher. Sie könnte uns den entscheidenden Hinweis geben, um die Ödnisbewohner für uns zu gewinnen. Töchter sind äußerst hilfreich.\n\nGeht mit Narathe. Gewinnt ihren Stamm für uns. Ich bleibe hier und leiste weitere Überzeugungsarbeit bei der Seelenschreiberin.", sourceObjective = "Findet eine Möglichkeit, die Ödnisbewohner auf Eure Seite zu ziehen.", completion = "In meinem Lager hat sich herumgesprochen, was Ihr für uns getan habt. Meine Tochter war schon immer viel zu vertrauensselig, aber Eure Anstrengungen sind nicht unbemerkt geblieben.", sourceObjectiveStatus = "unverified-source-field" }
quests[84868] = { id = 84868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hauch hilfreichen Rauchs", description = "Ihr scheint nun gut gerüstet für die Enthüllung von Geheimnissen! Ich gehe davon aus, dass Maru Euch am liebsten begleiten würde, aber dafür ist sie noch viel zu jung.\n\nGlücklicherweise verfügen wir Tuskarr über ein Räucherwerk, das die Kommunikation unserer Seelen über weite Strecken ermöglicht.\n\nIch habe etwas bei mir, falls Ihr Bedarf habt. Da Ihr mit Maru befreundet seid, berechne ich Euch auch nur die Kosten für Materialien.", sourceObjective = "Kauft spirituelles Räucherwerk bei Benatauk und gebraucht es.", progress = "Habt ihr das Räucherwerk ausprobiert?", completion = "Nun erkennt Ihr die Macht unserer spirituellen Verbindungen.\n\nHier, nehmt ein paar mit.", sourceObjectiveStatus = "unverified-source-field" }
quests[84869] = { id = 84869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glasjagd", description = "Brutale Plünderer aus der Leere wurden von Dimensius' Aura angelockt, um sich an dem zu laben, was er übrig lässt. Das stellt unsere lieben Ödnisbewohner vor ein Problem. Das Plündern ist ihre Aufgabe.\n\nSie könnten zwar auch alleine mit diesen Bestien klarkommen - ich wäre nicht auf ein Bündnis mit ihnen aus, wenn sie das nicht könnten - aber warum schenken wir ihnen nicht etwas, um ihnen zu demonstrieren, dass Ihr ebenso gut kämpfen könnt? Nein, sogar noch besser.", sourceObjective = "Tötet 4 Schrecken der Leere und 8 irreale Beobachter.", completion = "Die Ödnisbewohner respektieren Stärke und Brutalität. Ich denke, wir werden uns recht gut miteinander verstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84876] = { id = 84876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oase", description = "Die Seelenschreiberin würde für uns kämpfen und sogar sterben. Aber sie verweigert uns noch immer ihr Reshiiband. Sie betrachtet es als Werkzeug des Geflechts und ihr Eid steht unserer Mission im Weg.\n\nWenn sie noch einmal die Gegenwart der Weltenseele K'aresh spüren könnte, würde sie alles dafür geben, um sie zu beschützen. Sogar ihr Band. Die Oase ist die Biokuppel des Bundes mit einem stabilen Biom. Der ideale Ort, um mit einer Weltenseele zu kommunizieren, sollte es noch eine geben.", sourceObjective = "Trefft Xal'atath in der Oasen-Biokuppel.", progress = "Unsere Forschungsarbeiten sind entscheidend für die Zukunft K'areshs. Das wir diese Gegend stabilisiert haben, bedeutet, dass uns dies auch bei anderen Kuppeln gelingen kann und uns vielleicht sogar ermöglicht, die zerstörten Überreste von K'aresh zu heilen.", completion = "Das ist ein starker Regelverstoß. Ve'nari mag uns zwar gebeten haben, der Vorbotin und ihrem Champion mit äußerster Höflichkeit zu begegnen. Aber auch diesen barbarischen Ödnisbewohnern?\n\nHoffentlich weiß Ve'nari, was sie da tut.", sourceObjectiveStatus = "unverified-source-field" }
quests[84879] = { id = 84879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneuerte Hoffnung", description = "Diese Kuppel ist eine ordentliche Nachbildung K'areshs. Es gibt keinen besseren Ort, um die Seelenschreiberin das Lied der Weltenseele hören zu lassen.\n\nAber da Dimensius stärker wird, wird auch die Oase der Leere anheimfallen. Ich spüre bereits, wie sich Risse auftun. Ihre Energien werden dieses heikle Ritual stören. Leider müssen sie erst geschlossen werden, damit die Seelenschreiberin überzeugt werden kann.", sourceObjective = "Befreit die Biokuppel von invasiven Elementen.", progress = "Die Leere dringt täglich weiter nach K'aresh vor. Dimensius' Macht wird immer größer.", completion = "Es hängt eine Menge davon ab, dass dieses Tabiqaritual wie geplant läuft. Sie zu töten, um an ihr Band zu gelangen, wäre unschön.", sourceObjectiveStatus = "unverified-source-field" }
quests[84882] = { id = 84882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kartendeckchaos", description = "Sammelt die Karten ein, die im Gebiet verstreut wurden, und ich werde Euch auf ewig dankbar sein!", sourceObjective = "Sammelt die fehlenden Karten.", completion = "Ihr habt sie alle gefunden! Tausend Dank! Ich stehe für immer in Eurer Schuld!", sourceObjectiveStatus = "unverified-source-field" }
quests[84883] = { id = 84883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das einstige K'aresh", description = "Das Tabiqa durchzuführen, wurde seit tausenden Jahren nicht mehr versucht. Es war klar, dass der Verschlingerkrieg K'aresh zerstören würde.\n\nAber wenn ich mir diese Kuppel ansehe... dort wurde so vieles wiedererschaffen, das ich als auf immer verloren betrachtet hatte: Frisches Wasser, saubere Luft, selbst die Zaranitblumen, die ich für ausgestorben hielt. Sagt die Vorbotin die Wahrheit?\n\nNein. Ich habe meinen Eid nicht gebrochen und die Weltenseele im Stich gelassen. K'aresh gibt es nicht mehr.", sourceObjective = "Sammelt Materialien für das Ritual.", progress = "Habt Ihr die Komponenten für das Tabiqaritual gefunden? Gibt es sie überhaupt noch?", completion = "Diese Blüten wieder in Händen zu halten... ich hätte nicht gedacht, dass noch einmal erleben zu dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84885] = { id = 84885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeiten für G.E.T.A.", description = "Achtung! Beschützt die Bürger von Lorenhall UND werdet dafür bezahlt!\n\nProfitorientierte Kopfgeldjäger erhalten im örtlichen G.E.T.A.-Büro nähere Informationen.", sourceObjective = "Erkundigt Euch im örtlichen G.E.T.A.-Büro in den Bottichwerken.", progress = "Braucht Ihr etwas, {name}? Ich habe keine Zeit für Plaudereien.", completion = "Sowohl G.E.T.A. als auch die Bürger von Lorenhall sind bereit, für Eure Dienste und Eure Diskretion zu bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84891] = { id = 84891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. und die radioaktive Ratte", description = "Wir haben hier einen Bericht über eine große, radioaktive Ratte, die bis in einen nahe gelegenen Abwasserkanal verfolgt wurde. Sie ist nicht nur äußerst aggressiv, sondern auch eine Gefahr für die Umwelt.\n\nHe, seht mich nicht so an. Uns Lorenhallern sind diese Dinge nicht egal, auch wenn die großen Kartelle nicht daran interessiert sind.\n\nIch habe die Position des Kanaleingangs auf Eurer Karte markiert. Ich hoffe, einer dieser Idioten kriegt seinen Hintern hoch und schließt sich Euch dort an.", sourceObjective = "Besiegt die radioaktive Ratte.", progress = "Sobald Ihr fertig seid, kommt zurück, dann sorge ich dafür, dass Ihr angemessen entschädigt werdet.", completion = "So eine große Ratte habe ich nicht mehr gesehen, seit... Eigentlich glaube ich nicht, dass ich jemals eine so große Ratte gesehen habe. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[84892] = { id = 84892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. und der Krokodilian", description = "Wusstet Ihr, dass Krokodile unbegrenzt wachsen können?\n\nNun, der Besitzer dieses Krokodils wusste es nicht. Und als es zu groß wurde, wurde es ausgesetzt. Normalerweise verlassen diese Krokodile Lorenhall. Aber dieses Krokodil fand Gefallen am Geschmack der Goblins und blieb.\n\nDie Leute in Lorenhall könnten jemanden brauchen, der mutig genug ist, sich ihm zu stellen. Habt Ihr Lust?", sourceObjective = "Besiegt den Krokodilian.", progress = "Wer hat schon Angst vor einem großen Kroki, fragt Ihr?", completion = "Es ist geschafft. Die Menschen in Lorenhall wissen nicht, was Ihr getan habt, aber ich schon. Vielen Dank von uns allen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84893] = { id = 84893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. und der Kapitän", description = "Das ist ein einzigartiger Fall.\n\nEinige Höhlenspringer sind in die Abwasserkanäle von Lorenhall eingedrungen und fangen an, sich zu vermehren, was alle möglichen Probleme verursacht. Es sieht so aus, als würde ein besonders großer Springer sie irgendwie organisieren.\n\nWir haben ihm jetzt den Namen Kapitän gegeben.\n\nSorgt dafür, dass seine flossige, glubschäugige Schreckensherrschaft heute endet.", sourceObjective = "Bezwingt den Kapitän", progress = "Seid vorsichtig, {name}. Soweit wir wissen, arbeitet der Kapitän nicht allein.", completion = "Ich habe Höhlenspringer nie für übermäßig gefährlich oder organisiert gehalten. Offenbar gibt es eine Menge über sie, was wir noch nicht wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84894] = { id = 84894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.T.A. 2" }
quests[84896] = { id = 84896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nächste Dimension", description = "Bei K'areshs Liedern, ich werde mit Euch gegen die Schattenwache und Dimensius kämpfen. Sorgen wir dafür, dass jene, die es auf den ungezähmten K'aresh abgesehen haben, seine Anhänger fürchten!\n\nMeine Späher haben Eure Kameraden dabei beobachtet, wie sie eine Stellung im Gebiet der Schattenwache errichtet haben. Sie benötigen unsere Hilfe.\n\nK'aresh lebt! Wir kämpfen für eine gerechte Sache! Unser Eid bleibt ungebrochen!", sourceObjective = "Trefft Euch mit der Seelenschreiberin in Shan'dorah auf K'aresh.", completion = "Ich wusste gar nicht, dass es auf Eurer Welt so viele Leerenberührte gibt. Wie schützen sie ihre Seelen vor ihrem Wahnsinn?", sourceObjectiveStatus = "unverified-source-field" }
quests[84897] = { id = 84897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ruhe vor unserem Sturm", description = "Narathe hat recht. Zu unserem Glück, haben Leerenelfen Erfahrung im Kampf gegen die Schattenwache. Die Ödnis von K'aresh ist gnadenlos, genauso, wie es die bevorstehende Schlacht sein wird. Hoffentlich sind sie für diesen brutalen Kampf gewappnet. Dieses Mal geht es nicht gegen versprengte Späher, wie sie es auf Telogrus gewohnt sind.\n\nIhr solltet dafür sorgen, dass sie für die bevorstehende Schlacht bereit sind.", sourceObjective = "Schaut nach Alleria und den Leerenelfen in Shan'dorah auf K'aresh.", progress = "Auf diesen Augenblick haben wir uns lange vorbereitet. Ich werde ihn nicht verpassen.", completion = "Diese Elfen sind härter als gedacht. Vielleicht hat die Not unsere beiden Völker abgehärtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[84898] = { id = 84898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sande von K'aresh", description = "Mein Volk hat um jeden Zentimeter der Ruinen unserer Welt gekämpft. Wir haben es König Salhadaar geschworen und er hat uns zum Lohn die Schattenwache auf den Hals gehetzt.\n\nSalhadaar ist zwar schon lange tot, aber wir wussten, dass die Schattenwache zurückkehren würde. In den langen Jahren danach haben wir geheime Waffenlager angelegt, damit wir uns immer verteidigen können.", sourceObjective = "Sammelt 3 Waffentruhen aus den nahen Sanden der Trümmerschlucht auf K'aresh.", completion = "Die sind gut. Sie sind immer noch scharf. Ich werde damit mein Volk und Eure Verbündeten bewaffnen. Für K'aresh, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[84899] = { id = 84899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbreitung der Schattenwache", description = "Die Schattenwache ist mir schon lange ein Dorn im Auge, ob nun mit Xal'atath oder ohne sie. Es wäre klug, auf diesem Felsen so viele wie möglich von ihnen auszuschalten. Ich traue ihr zwar noch immer nicht, aber wir müssen uns auf den Gegner konzentrieren, den wir jetzt gerade bezwingen können.\n\nHabt kein Mitleid, {name}. Wenn Ihr eine Schattenwache seht, streckt sie nieder. Wenn wir sie heute bekämpfen, müssen wir das nicht morgen tun.", sourceObjective = "Bezwingt Schattenwachen in den Sanden der Trümmerschlucht um Shan'dorah auf K'aresh.", completion = "Gut gemacht, {name}. Wenn die Schattenwache blutet, werden die Sande getränkt.\n\nBis zum Sieg müssen wir noch viele weitere von ihnen erschlagen. Aber es wird noch eine Zeit zum Feiern kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84900] = { id = 84900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ein Buttermesser durch den Äther", description = "Sehr gut, mein Champion. Ihr seid eine schnelle, scharfe Klinge der Zerstörung.\n\nUnd diese Macht werden wir nun in voller Gänze einsetzen. Wir werden die Schattenwachen niedermetzeln, die Dimensius erwecken wollen und die Maschinen, die seinen unersättlichen Hunger stillen sollen.\n\nDie Schattenwache muss ein Reshiiband erbeutet haben. Haltet nach diesem letzten Band Ausschau, wenn wir ihre Garnisonen zerstören. Dann können wir einen Leerenfürsten töten.", sourceObjective = "Stoppt die Astralen der Schattenwache am Schattenpunkt: Dunkelheil in K'aresh.", progress = "Noch ein paar mehr, dann könnten wir eine Chance haben. Lasst nicht nach, {name}. Ihr könnt das und noch so viel mehr.", completion = "Noch zwei. Zwei weitere Orte, an denen das Band versteckt worden sein könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[84902] = { id = 84902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einsatz zum Bösen", description = "Zu Energiewesen zu werden, war eine Entscheidung, bei der wir keine andere Wahl hatten. Seitdem sind wir zum Überleben darauf angewiesen, uns von Energie zu ernähren.\n\nDie Schattenwache speist damit Dimensius. Sein Hunger ist unstillbar und er wird K'aresh Energie entziehen, um wiederaufzuerstehen. Wir müssen die Maschinen zerstören, die ihn versorgen, {name}.", sourceObjective = "Deaktiviert 6 Energiepylonen der Schattenwache am Schattenpunkt auf K'aresh.", progress = "Sind sie alle tot?", completion = "Die Technomantie meines Volkes könnte zu großem und segensreichem Nutzen eingesetzt werden. Doch immer wieder gebrauchen wir sie für großes Übel. Mit dem Erstarken von Dimensius' Macht schwinden wir alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[84903] = { id = 84903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis der Sand Leere blutet", description = "Ich habe gegen die Schattenwache auf Eredath, Telogrus und nun auf K'aresh gekämpft. Sie ist ein Dorn im Gefüge des Kosmos und muss endlich entfernt werden.\n\nDass sie jenem Monster folgen, das einst ihre Welt bedrohte, beweist, dass sie eine Plage sind. Und doch, vielleicht bin ich nicht besser, da ich an der Seite von Xal'atath kämpfe.\n\nMit diesem Widerspruch werde ich mich später auseinandersetzen. Jetzt habe ich vor, ihnen ein Ende zu setzen, {name}.", sourceObjective = "Tötet Schattenwächter am Schattenpunkt auf K'aresh.", completion = "Ist dies das Schicksal der Ren'dorei? Werden auch wir, wenn nur genug Zeit vergeht, den Mächten dienen, gegen die wir heute kämpfen? Ich habe den Raumgänger stets als Vorbild gesehen, dem wir nacheifern könnten. Doch nun scheint es, als müssten die Ren'dorei ihren eigenen Weg finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84904] = { id = 84904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und wir werden antworten", description = "Das ist undenkbar. Ketzerei!\n\nDie Schattenwache hat meine Krieger gefangen genommen, verwandelt sie in neue Truppen für Dimensius und zwingt sie, dem alles Verschlingenden einen Schwur zu leisten, während sie von der Leere erfüllt werden.\n\nBefreit sie, {name}. Wir dürfen das nicht länger hinnehmen. Ich werde Narathe entsenden, um Euch im Kampf beizustehen. Sie weiß, wie man die Seelen von Eidbrechern befreit.", sourceObjective = "Rettet gefangene Ödnisbewohner am Schattenpunkt auf K'aresh.", completion = "Wie viele sind Eurer Ansicht nach verloren?\n\nIch habe eine Pflicht gegenüber meinem Volk. Lasst uns das beenden, damit niemand erneut gezwungen wird, dem alles Verschlingenden zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84905] = { id = 84905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Schatten wandeln", description = "Wir müssen weiterhin diese Gebäude deaktivieren oder zerstören. Ich verabscheue es, die Technologie meines Volkes zu zerstören, doch wenn sie für solch einen düsteren Zweck missbraucht wird, bleibt keine Wahl!\n\nHaltet Euch von jetzt an nicht mehr zurück. Lasst uns die Werke der Schattenwache vernichten.", sourceObjective = "Helft dem Raumgänger, den Schattenpunkt: Qual am Schattenpunkt auf K'aresh zu deaktivieren.", completion = "Vor uns liegt nur noch mehr Dunkelheit. Macht Euch auf alles gefasst.", sourceObjectiveStatus = "unverified-source-field" }
quests[84906] = { id = 84906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nexuskönigsmord", description = "Der Moment ist gekommen, {name}.\n\nWir dürfen nicht zögern. Sie werden ihre stärksten Krieger entsenden, um diese letzte Manaschmiede zu verteidigen. Dort werden wir Nexusprinz Azir antreffen und ihm den Garaus machen, bevor es in den Kampf gegen Dimensius geht. Xal'atath hin oder her, wir haben, was wir brauchen, um es zu schaffen. Noch ein letzter Toter.\n\nLasst uns keine Zeit verlieren. Beeilt Euch.", sourceObjective = "Besiegt den Anführer der Schattenwache an Schattenpunkt: Apotheose auf K'aresh.", completion = "Hm.\n\nDiese Lektion ermüdet mich, {name}. Immer wenn wir uns jemandem nähern, werden wir verraten. Sie wanken. Sie wenden sich ab. Sie sterben. Immer wieder setzen wir sie Gefahren aus und schaffen es nicht, sie zu beschützen.\n\nLasst nicht zu, dass sich uns noch jemand in den Weg stellt. Ihr und ich, {name}. Wir bringen das zu Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[84908] = { id = 84908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Sturmreiters Ehre", sourceObjective = "Sprecht mit Sturmreiterin Bruelda in Dornogal.", completion = "Was gibt's?", sourceObjectiveStatus = "unverified-source-field" }
quests[84909] = { id = 84909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterhafte Feierkiste", description = "<Die Kiste sendet ein geisterhaftes Leuchten aus, und Ihr spürt die Präsenz geheimnisvoller Geister. Alyx würde sich über die Vorräte freuen.>", sourceObjective = "Bringt die geisterhafte Feierkiste zu Alyx zurück.", progress = "Ja?", completion = "Oh, Ihr habt eine fehlende Kiste gefunden! Wunderbar!\n\nIch bin wirklich dankbar, dass Ihr sie zurückgebracht habt. Wenn Ihr noch mehr findet, bringt sie bitte auch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[84910] = { id = 84910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tabiqa", description = "Meine Gefolgsleute sehnen sich nach den Tagen, da sie Orakel waren. Sie sehnen sich danach, das Lied von K'aresh zu hören. Ich aber bin Realist. Die Bosheit des Geflechts, von Dimensius... Sie haben die Schönheit zerstört, die einst unsere Weltenseele war.\n\nDoch Ihr habt die Gegenstände für das Tabiqa zusammengetragen. Darum werde ich es versuchen. Wenn ich die Leere von K'areshs Abwesenheit höre, wird das Konsequenzen haben.", sourceObjective = "Helft der Seelenschreiberin mit dem Ritual.", progress = "Es ist zu lange her, dass wir K'aresh so nah waren. Es ist nur noch ein Echo dessen, was einst war, doch die Erinnerungen, die es zurückbringt...", completion = "Und schon kommt alles zusammen. Möglicherweise haben wir genug Kraft, um uns der Schattenwache zu stellen, Champion.\n\nLasst mich das Blatt noch weiter zu unseren Gunsten wenden. Mithilfe dieser Reshiibänder werde ich die Reshiiwickel mit genug Macht erfüllen, damit Ihr den ungebundenen Raum erkunden könnt... um Kraft für den bevorstehenden Kampf zu sammeln.\n\nGern geschehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84912] = { id = 84912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Show muss weitergehen!", description = "Danke, dass Ihr gekommen seid! Uns ist ein kleines Missgeschick mit dem Skript und verschiedenen Bühnenrequisiten passiert.\n\nAlles ist verschwunden! Irgendein Witzbold muss wohl beschlossen haben, sich über unsere Produktion lustig zu machen und mehrere wichtige Gegenstände überall in der Gegend zu verstreuen.\n\nWenigstens war dieser Witzbold noch so nett und hinterließ ein paar Hinweise, wo wir die verschwundenen Gegenstände finden können. Glaubt Ihr, Ihr schafft es, die Rätsel zu lösen?\n\nUnd bitte lauft nicht mit offenem Feuer herum oder leuchtet mit hellem Licht, wenn Ihr unser Theater durchsucht.", sourceObjective = "Helft Schmucktau am Amphitheater im Ardenwald.", progress = "Nutzt die Abspielliste, um die fehlenden Gegenstände im Gebiet zu finden.", completion = "Das Theater dankt Euch für Euren tapferen Einsatz an diesem Tag!", sourceObjectiveStatus = "unverified-source-field" }
quests[84914] = { id = 84914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapferkeitssteine", sourceObjective = "So hilfreich! Kobolde danken Euch. Irdene danken Euch. Die Versammlung dankt Euch! \n\nKerze für Euch! Keine bessere Belohnung als das!\n\nNein, diese Kerze nicht aus Ohrenschmalz gemacht. Ist aus Bienenwachs! Riecht so gut! Ihr mögt schöne Gerüche, ja? Wenn nicht, wollt Ihr vielleicht von mir weggehen, ha, ha, ha! Entschuldigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[84915] = { id = 84915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dünen säubern", description = "Die Wüsten hier waren noch nie wirklich sicher, doch es gab hier einst Schönheit. Vogelgesang, Tierherden, und nach einem Sturm blühte die Wüste bis zum Horizont.\n\nJetzt ist alles eine Einöde. Ich hatte kaum zwei Schritte vom Dock gemacht, da jagte mir schon irgendein Monster hinterher. Ich muss weg. Wenn Ihr die schlimmsten dieser Kreaturen ausmerzen könntet, würde ich mich deutlich sicherer fühlen.", sourceObjective = "Tötet 8 Dünenkreaturen.", completion = "Es scheint, als hätten nur die grausamsten Kreaturen außerhalb der Biokuppeln überlebt. Wenn wir meine Schwester finden, werde ich sie nach Tazavesh zurückbringen. Dort ist es sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[84923] = { id = 84923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte eines Vogels", description = "Ich habe gehört, dass Reshad eine neue Geschichte über seinen Vogelbegleiter Percy erzählen möchte. Sprecht mit ihm, wenn Ihr die Geschichte hören möchtet.", sourceObjective = "Sucht Reshad in der Nähe der Bühne auf.", completion = "Hallo. Möchtet Ihr Percys Geschichte hören?", sourceObjectiveStatus = "unverified-source-field" }
quests[84924] = { id = 84924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus der Feder eines Vogels", description = "Ich habe schon mein ganzes Leben Geschichten erzählt, aber mein Begleiter Percy kann seine ganz eigene Geschichte erzählen. Möchtet Ihr sie hören?\n\nIch gebe Euch einen Hinweis, wo Ihr anfangen solltet. Von dort aus müsst Ihr Percys hinterlassene Hinweise finden, um seine Geschichte zu erfahren.\n\nIhr könnt auch diese Feder haben, die Percy zurückließ. Seht genau hin und vielleicht spürt Ihr weitere Hinweise auf. Möglicherweise kann Euch ein eigener Vogel auf Eurem Weg helfen.", sourceObjective = "Erfahrt mehr über Percys Abenteuer, indem Ihr seine Federn findet.", completion = "Ah, Ihr seid zurück. Lasst mich mal sehen, welche Hinweise Ihr aufgespürt habt...\n\nSieh an, sieh an, was für ein umtriebiger Vogel. Percy kam mit einem Schiff am Frostfeuergrat an, wo Ihr eine seiner Federn gefunden habt.\n\nAls Nächstes reiste er durch Nagrand nach Shattrath, wo er offenbar in irgendeinen Konflikt hineingeraten ist!\n\nUnd schließlich kam er an den Spitzen von Arak an, wo er mit mir wiedervereint wurde. Was für ein Abenteuer für unseren Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[84925] = { id = 84925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauner, gruppiert Euch!", description = "Hört, hört! Seht her! Kommt alle nach Dornogal!\n\nZusätzlich zur gewohnten Auswahl an mächtiger Ausrüstung, die am Rivalentor angeboten wird, können aufstrebende Kämpfer und erfahrene Gladiatoren auch Wappenmarken kaufen, die zur Herstellung von Ausrüstung verwendet werden können, die in Arenen und auf Schlachtfeldern zugelassen ist!\n\nReicht diese Broschüre bei Hotharn ein, um ein paar davon zu erhalten - kostenlos, aufs Haus!\n\n- Aisha", sourceObjective = "Gebt die Broschüre bei Hotharn am Rivalentor in Dornogal ab.", completion = "Ah, ich hatte mich schon gefragt, wann die ersten eifrigen Kämpfer auftauchen werden. \n\nHier, nehmt das, wie versprochen. Benutzt sie, wenn Ihr Handwerksaufträge einreicht oder Eure eigene Ausrüstung herstellt. Das Ergebnis wird genauso mächtig sein wie das, was Lalandi da drüben verkauft, aber diese Teile sind großartig, wenn Ihr etwas Individuelles möchtet, das auf Eure Bedürfnisse abgestimmt ist. Wenn Ihr mehr braucht, wisst Ihr, wo Ihr mich findet.\n\nFragen? Hebt sie Euch für die Schmiedegründe auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[84929] = { id = 84929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebensretter im Einsatz" }
quests[84932] = { id = 84932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vermächtnis der Zerstörung", description = "<Abenteurer/Abenteurerin>! Vor Kurzem ist ein Drachenwelpling in der Nähe des Haustierspielplatzes aufgetaucht und sorgt richtig für Chaos.\n\nKönntet Ihr mit ihm sprechen und versuchen, sein Problem zu lösen?", sourceObjective = "Sucht den Drachenwelpling am Haustierspielplatz auf.", completion = "Roaaar! Ich werde ALLES niederbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[84933] = { id = 84933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Asche zur Weisheit", description = "Ich werde die große und mächtige Todesschwinge! Zittert und verneigt Euch vor meiner Stärke!\n\nIhr da! Wollt Ihr Euch nicht mir, der nächsten Todesschwinge, für ein episches Abenteuer anschließen?", sourceObjective = "Zeigt Leerenfeuer die Vernichtung von Todesschwinge.", progress = "Ich will eine große böse Narbe auf der Welt hinterlassen! Narben sehen schick aus, oder?", completion = "Na gut, ich schätze, Sachen verbrennen, Landstriche überfluten und Kults gründen macht nicht so viel Spaß, wie es klingt... Alles, was Todesschwinges Einfluss zu spüren bekommt, wird trostlos und macht gar keinen Spaß mehr.\n\nIch werde eher wie Nozdormu! Der ist ziemlich eindrucksvoll und hat Zeitreisen und so was.", sourceObjectiveStatus = "unverified-source-field" }
quests[84935] = { id = 84935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Einfall eindämmen", description = "Die Verschlingende Schar muss uns irgendwie hierher gefolgt sein.\n\nIch weiß nicht, was sie mit so einem Ort anfangen wollen, aber ich kann mir nicht vorstellen, dass die Leere plötzlich wohlwollende Absichten verfolgt. Wir dürfen sie nicht einfach gewähren lassen.\n\nTötet so viele von ihnen, wie Ihr könnt. Zumindest genug, um ihre Reihen zu lichten.", sourceObjective = "Tötet Entartungen der Verschlingenden Schar in den Ebenen der Qual.", completion = "Wir haben eine Lücke in ihre Reihen geschlagen, aber so schnell, wie sie vorrücken, werden sie den ganzen Schlund überrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84936] = { id = 84936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schatten läutern", description = "Diese Monstrositäten haben seit ihrem Eintreffen wahrlich keine Zeit vergeudet. Sie ergreifen überall Seelen und ertränken sie in Leerenmagie.\n\nNehmt mein heiliges Symbol. Es sollte stark genug sein, um die Schatten zu vertreiben, die sich an die verweilenden Seelen klammern.", sourceObjective = "Nutzt das Siegel des Erlösers, um die leerenverzerrten Seelen in den Ebenen der Qual zu läutern.", completion = "Ich konnte die Reaktionen auf die Läuterung von hier aus sehen. Ich hatte ja keine Ahnung, dass meine Methoden so ungeeignet dafür sein würden, die Seelen dieses Ortes zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[84937] = { id = 84937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ferne Echos", description = "Hört Ihr das auch? Diesen seltsamen Klang, der in der Ferne widerhallt. Bedenkt man, wo wir sind, gehe ich von einem Trick aus. Oder schlimmer, einer Falle. Aber es fühlt sich...\n\nIch weiß nicht, wie ich es beschreiben soll, aber der Klang beruhigt mich irgendwie. Als hätte ich die Kontrolle.\n\nDas hört sich jetzt verrückt an, aber ich glaube... Ich glaube, wir sollten ihm folgen. Ich weiß nicht, wo er herkommen könnte, aber meine Instinkte sagen mir, dass ich ihm trauen kann. Wir sollten seiner Spur folgen.", sourceObjective = "Findet den Ursprung der seltsamen Melodie.", progress = "<Sylvana mustert Euch schweigend von oben bis unten.>", completion = "Um ehrlich zu sein, hätte ich mir denken können, dass dies Euer Werk ist. Ihr habt ein beachtliches Talent dafür, den Frieden zu stören. Es ringt mir fast schon Respekt ab.\n\nIch hätte allerdings nie damit gerechnet, an solch einem Ort meinem Neffen zu begegnen.\n\nUnwichtig. Wenn Ihr schon hier seid, könnt Ihr auch den Schlamassel beseitigen, den Ihr angerichtet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84938] = { id = 84938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaoskontrolle", description = "Das sind keine reinen Verkörperungen der Leere. Sie bewegen sich mit Präzision und einem klaren Ziel. Sie haben eine Verteidigungsposition innerhalb des Tremaculums eingenommen. Zweifelsohne wollen sie nun, nachdem sie hier Fuß gefasst haben, ihre Präsenz weiter ausbauen und ihre Verteidigung verstärken.\n\nUmso besser. Das bedeutet, dass sie alle an einem Ort versammelt sind.\n\nDurchbrecht ihre Reihen. Zeigt keine Gnade.", sourceObjective = "Dämmt die Flut der Verschlingenden Schar innerhalb des Tremaculums ein.", completion = "Ihr seid so todbringend wie eh und je. Und ich war ernsthaft besorgt, der Frieden könnte Euch abgestumpft haben.\n\nKommt. Wir sind noch nicht fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[84939] = { id = 84939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ort des Wahnsinns", description = "Es spielt keine Rolle, wie viele dieser Leerenmonstrositäten wir töten. Wir müssen uns um die Quelle kümmern, sonst kommen sie immer wieder.\n\nEine Reise durch den Riss ist selbst in guten Zeiten kein leichtes Unterfangen. Wenn wir die Orte ausfindig machen und verschließen können, an denen sie durchgebrochen sind, schneiden wir sie damit von ihrer Verstärkung ab.\n\nIhr geht vor. Ich bin die ganze Zeit hinter Euch.", sourceObjective = "Lasst 5 instabile Leerenrisse zusammenbrechen.", progress = "Dieser Ort wimmelt von Dienern der Leere. Seid auf der Hut.", completion = "In gewisser Weise ist das hier eine wichtige Lektion. Ein wahrer Paladin kämpft nicht nur dann, wenn die Finsternis sich manifestiert. Er sucht nach der Quelle.", sourceObjectiveStatus = "unverified-source-field" }
quests[84940] = { id = 84940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freundlicher Wettbewerb", description = "Ricket hat angeboten, ihn auszugraben, aber die Dame von der Expedition der Arathi schien davon nicht begeistert zu sein.\n\nHat ihr eine Standpauke gehalten. Hat man vom Luftschiff aus gehört. Herrje.\n\nBargus, der irdene \"Richter\", was auch immer das heißen mag, schlug vor, den Kristall zu scannen, damit wir ihn \"besser verstehen\" können.\n\nIch brauche ihn nicht zu verstehen. Alles, was ich brauche, ist meinen Anteil. Aber ich kann mich gerne zurückhalten und tun, was sie wollen.\n\nRedet mit Bargus im Lager der Irdenen. Findet heraus, wie sie vorankommen und ob wir helfen können.", sourceObjective = "Sucht Bargus im Lager auf.", completion = "<Bargus blickt von seinem Amboss auf.> \n\nEin Neuankömmling. \n\nSeid Ihr hier, um unsere Bemühungen zu unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[84941] = { id = 84941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhleneinsturz", description = "Wer auch immer diese großen Fremdlinge sind, sie scheinen sich auch für das Signal des Kristalls zu interessieren, und für den Ort seiner Herkunft, wenn es kein Zufall ist.\n\nWir Irdenen halten nicht viel von Zufällen.\n\nAktiviert Eure Verteidigungsprotokolle, {name}.\n\nDiese Fremdlinge sind nicht so gastfreundlich wie Euer Volk.", sourceObjective = "Findet heraus, woher die Energiesignatur stammt.", completion = "<Bargus sieht sich in den zerfallenen Ruinen der Höhle um.>\n\nDie Kristalle auf der Tafel...\n\nWenn diese kleinen Kristalle die Quelle der neuen Energiesignatur sind, warum werden sie dann stärker angezeigt als die größere Facette auf der Oberfläche?\n\nEs gibt noch etwas anderes, das wir übersehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[84942] = { id = 84942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Bedrohung", description = "Nun, da ihre kleineren Risse geschlossen sind, wird die Verschlingende Schar Schwierigkeiten haben, Verstärkung zu mobilisieren. Aber wenn wir uns nicht um ihren Anführer kümmern, werden sie einfach noch mehr öffnen.\n\nOben, auf den Brüstungsmauern... Es gibt keinen Zweifel. Ich kann selbst von hier unten spüren, wie dort eine Kraft der Leere alles zu sich zieht. Das ist unser Ziel.", sourceObjective = "Bezwingt das lebendige Tor an der Spitze des Tremaculums.", progress = "Jetzt müssen wir uns nur noch um ihren Kommandanten kümmern.\n\nIch wünschte nur, er hätte eine etwas niedriger gelegene Stellung gewählt.", completion = "Das Gros der verbleibenden Bedrohung ist im Tremaculum gebunden. Nun, da ihre Kommandanten getötet und ihre Portale geschlossen sind, sollten sich die natürlichen Bewohner des Schlunds schon bald der Überbleibsel annehmen.\n\nGeht jetzt. Ich habe Arbeit zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84943] = { id = 84943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die lange Wacht", description = "Wenn Ihr und Arator etwas von mir wollt, muss es warten. Es gibt Seelen hier, um die ich mich kümmern muss. Vorausgesetzt, Euer tollpatschiges Verhalten hat sie nicht vertrieben.\n\nIch konnte vier Seelen ausmachen, die in den Schlund gefallen sind, ohne ihr Urteil erhalten zu haben. Macht Euren Fehler wieder gut und helft mir, sie zurückzuholen. Dann finde ich vielleicht Zeit für ein Gespräch.", sourceObjective = "Findet und beruhigt vier verlorene Seelen in den Ebenen der Qual.", progress = "Ich nehme meine Buße ernst, Schlundgänger.\n\nIm Gegensatz zu Euch, wie es scheint. Findet die Seelen oder geht mir aus den Augen.", completion = "Ich sehe diesen Ausdruck in Euren Augen. Habt Ihr geglaubt, dass dies eine einfache Aufgabe ist? Nicht alle sind gewillt oder bereit, geborgen zu werden.\n\nEs spielt keine Rolle. Sie bestehen fort und treffen ihre Wahl. Manchmal reicht das aus, um den Schmerz zu lindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[84944] = { id = 84944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorspiele und Vorbereitungen", description = "Wie Ihr zweifellos wisst, ist es keine leichte Aufgabe, Seelen aus dem Schlund herauszuführen. Dies ist kein Ort, von dem Seelen aufsteigen sollen.\n\nUnsere Mittel sind begrenzt, aber ich habe eine Methode entwickelt, um die relative Sicherheit der Seelen, die ich zurückhole, zu gewährleisten. Dafür benötige ich allerdings Materialien. Bringt mir das Schilf, das im Gorgoafluss wächst, Seelenfäden aus den Umhängen der umherwandernden Geister, den Balg eines Seelenfressers... Ah, und Schlundrattenzähne.\n\nDie Schlundrattenzähne dürfen wir nicht vergessen.", sourceObjective = "Sammelt Gorgoaschilfrohr, Seelenfäden, einen makellosen Seelenfresserbalg und 50 Schlundrattenzähne.", progress = "Habt Ihr die Reagenzien schon?", completion = "Es ist seltsam. Ich weiß nicht, wie ich es sagen soll, aber Sylvanas so zu sehen... In gewisser Hinsicht ist sie, wie ich sie mir immer vorgestellt habe.\n\nIch weiß, es ist als Buße gedacht. Und es ist bestimmt nicht einfach. Aber sie scheint so mit sich im Reinen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[84945] = { id = 84945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Buße der Hochgeborenen", description = "Die Reagenzien sind zusammengetragen und die verweilenden Seelen wurden fürs Erste beruhigt.\n\nUns bleibt nicht viel Zeit. Tretet zurück, während ich sie dorthin schicke, wo sie eigentlich weilen sollten.", sourceObjective = "Beobachtet das Ritual der Überführung.", progress = "<Sylvanas steht still da.>", completion = "Es ist vollbracht.\n\nMorgen wird es mehr geben. Und am Tag danach. Bis nur noch ich bleibe.", sourceObjectiveStatus = "unverified-source-field" }
quests[84947] = { id = 84947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entschlossenheit", description = "Wartet einen Augenblick.\n\nArator kommt noch ein wenig länger zurecht. Lasst ihn einen Augenblick allein reisen.\n\nIch möchte mit Euch sprechen. Unter vier Augen.", sourceObjective = "Sprecht mit Sylvanas.", completion = "Es versteht sich von selbst, dass Ihr und ich nicht immer einer Meinung waren. Dennoch bin ich Euch dankbar. Arator ist ein naiver Narr, aber er gehört zur Familie.\n\nJetzt geht. Sorgt dafür, dass er sicher nach Hause kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84948] = { id = 84948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertragsarbeit" }
quests[84949] = { id = 84949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die elfte Stunde", description = "Es ist höchste Zeit, dass wir nach Azeroth zurückkehren. Ich denke, wir haben alles getan, um die Windläufer für das, was kommt, vorzubereiten.", sourceObjective = "Kehrt zu Vereesa in Dornogal zurück.", progress = "Lasst uns aufbrechen. Ich habe für heute genug Dimensionsreisen gemacht, denke ich.", completion = "Danke, dass Ihr mich auf dieses Abenteuer begleitet habt, {name}. Es ist etwas außer Kontrolle geraten, aber ich denke, es hat sich trotzdem gelohnt.\n\nIch hoffe, unsere Warnungen haben genügt. Jetzt, da Xal'atath über ihre Armee und die Macht eines Leerenfürsten verfügt, will ich mir gar nicht vorstellen, welche Schrecken sie zu entfesseln plant.", sourceObjectiveStatus = "unverified-source-field" }
quests[84955] = { id = 84955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmuggelgut ungut" }
quests[84956] = { id = 84956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schattenhafte Einladung", sourceObjective = "Trefft den Raumgänger in der Gründungshalle in Dornogal.", completion = "Die Schattenwache wird vor nichts Halt machen, um den Leerenfürsten Dimensius wiederzubeleben. Und wir sollten besorgt sein, denn meine Heimat wurde von diesem Monster zerstört. Es ist kein Geheimnis, wie alles endet, wenn es nicht aufgehalten wird.\n\nAber ich arbeite bereits an einem Plan... eigentlich eher an einer Notfallmaßnahme, und nun ist es an der Zeit, sie umzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84957] = { id = 84957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Verhüllten Markt", description = "Ich wurde vom Bund von K'aresh engagiert, einer Koalition aus Kartellen von Mittlern und Astralen, die K'aresh zurückerobern wollen. Der Bund benötigt dringend eine Eurer Fähigkeiten, {name}.\n\nDie Schattenwache greift unsere Stadt an und bedroht die Arbeit am Projekt der Biokuppel.\n\nBitte begleitet mich.", sourceObjective = "Begleitet Alleria und den Raumgänger nach Tazavesh.", completion = "Willkommen in Tazavesh, Ihr zwei.\n\nWir haben viel zu besprechen. Eure Hilfe ist, wie immer, von entscheidender Bedeutung.", sourceObjectiveStatus = "unverified-source-field" }
quests[84958] = { id = 84958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebändigte Bestien", description = "Ich bin Ta'ka, Lieferant seltener Kreaturen, die meine Heimat neu bevölkern sollen.\n\nZumindest war ich das, bis einige von ihnen aus ihren Translokationskäfigen entkamen! Das darf nicht sein!\n\nDiese Kreaturen sind von entscheidender Bedeutung. Wenn Ihr mir bei der Jagd nach ihnen helfen könntet, wäre ich Euch sehr dankbar.\n\nTretet gegen sie an und bezwingt sie. Das von mir bereitgestellte Einfanggerät bringt sie automatisch zu mir zurück, sobald sie kurz vor der Niederlage stehen.", sourceObjective = "Besiegt die entflohenen Kreaturen in Tazavesh und bringt sie zu Ta'ka zurück.", progress = "Habt Ihr die entflohenen Bestien bereits gefangen?", completion = "Ihr habt sie zurückgebracht! Ausgezeichnete Arbeit.\n\nHier ist Eure Belohnung, wie versprochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84959] = { id = 84959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Verteidigungslinien", description = "Das ist kein guter Tag! Ganz und gar nicht! Meine gesamte Lieferung an Barrierenprojektoren wurde geplündert! Die meisten sind verschwunden, und es scheint, dass die Übeltäter alles zerstört haben, was sie nicht mitgenommen haben.\n\nDiese Barrierenprojektoren sind entscheidend, um die Wildnis auf K'aresh und sogar die Stadt Tazavesh abzusichern. Unsere gesamte Arbeit steht auf dem Spiel!\n\nBitte, wenn Ihr irgendeine meiner Lieferungen finden könntet, würde es uns helfen, unsere Arbeit fortzusetzen.", sourceObjective = "Sammelt 8 gestohlene Barrierenprojektoren für Ba'ver.", progress = "Habt Ihr meine Barrierenprojektoren aufgespürt?", completion = "Ausgezeichnet! Mit diesen Projektoren können wir unsere Heimat erneut sichern.\n\nHabt Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[84960] = { id = 84960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkelheit unter uns", description = "Alleria, {name}... Habt Ihr es gespürt? Die Leere schwebt über allem hier. Wer auch immer hier die Fäden zieht, ist in Schatten gehüllt und verbirgt sich vor uns.\n\nKommt, lasst uns nach dem Verantwortlichen suchen und ihn ans Licht zerren, bevor er zuschlägt.", sourceObjective = "Untersucht die Präsenz der Leere und spürt die Übeltäter hinter den vielen Problemen in Tazavesh auf.", progress = "Wir müssen den versteckten Schattenwächter entdecken, {name}.", completion = "Die Schattenwache! Natürlich stecken diese leerenverseuchten Narren dahinter. Ich hätte es wissen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[84961] = { id = 84961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrieren als Zugang", description = "Wir brauchen jetzt die Barrierenprojektoren, die wir zurückgeholt haben. Platziert sie an entscheidenden Punkten, um den Stadtschild zu verstärken und das Entstehen weiterer Portale zu verhindern.\n\nBeeilt Euch, {name}. Das könnte unsere einzige Chance sein, die Schattenwache aufzuhalten.", sourceObjective = "Platziert 8 Barrierenprojektoren um Tazavesh herum.", progress = "Habt Ihr die Barrierenprojektoren platziert? Wir müssen die Invasion verlangsamen. Schnell!", completion = "Gut gemacht. Der Schild um die Stadt sieht bereits stärker aus.\n\nDas sollte uns etwas Zeit verschaffen gegen die Schattenwache.", sourceObjectiveStatus = "unverified-source-field" }
quests[84962] = { id = 84962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Auslöschung" }
quests[84963] = { id = 84963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versiegelung der Schatten", description = "Nein, nein, nein! Die Schattenwache plündert die Stadt, und unsere Verteidigung wird immer schwächer! Wir haben sogar in neue Sicherheitsgolems investiert, nachdem die Stadt beim letzten Angriff überfallen wurde, aber wir hatten keine Zeit, sie zu aktivieren.\n\nWartet... Ich habe eine Idee. Einige der Schattenwächter müssen Entropiekerne geplündert haben, die wir zur Aktivierung der Golems nutzen können.\n\nBitte, Ihr müsst sie besiegen und diese Kerne beschaffen. Wir müssen die Golems in Betrieb nehmen, um unsere Investitionen zu schützen! Ähm, ich meine, unsere Stadt!", sourceObjective = "Sammelt 5 gesättigte entropische Kerne der Schattenwache in Tazavesh.", progress = "Habt Ihr die Kerne, die Om'en wollte?", completion = "Diese scheinen in gutem Zustand zu sein! Gut, dann lasst uns mit dem nächsten Schritt dieses Plans fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[84964] = { id = 84964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden im Schatten", description = "{name}! Dies mag nicht mein Volk sein, aber wir können nicht einfach zusehen, wie es von der Schattenwache niedergestreckt wird. Ihr und ich, wir können etwas bewirken!\n\nWir müssen da rausgehen, die Zivilisten retten und sie in Sicherheit bringen. Die Stadt mag im Chaos versinken, aber wir können trotzdem der Schild sein, den sie brauchen.", sourceObjective = "Rettet 8 Zivilisten von Tazavesh.", progress = "Da sind noch Leute da draußen, {name}!", completion = "Gut. Wir haben hier etwas bewirkt!", sourceObjectiveStatus = "unverified-source-field" }
quests[84965] = { id = 84965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernbeiträge", description = "Die entropischen Kerne, die wir gesammelt haben, werden entscheidend für unsere Verteidigung sein.\n\nNutzt sie, um die in der Stadt verteilten Marktwächter zu reaktivieren. Einmal aktiviert, werden diese Golems sich unserem Kampf anschließen und uns dabei helfen, die Eindringlinge zurückzudrängen.\n\nDie Zeit drängt, {name}. Das Schicksal von Tazavesh liegt in Euren Händen.", sourceObjective = "Aktiviert 5 Marktwächter, die in Tazavesh verteilt sind.", progress = "Jeder von uns aktivierte Wächter sollte helfen, die Lage zu stabilisieren.", completion = "Ausgezeichnet! Das ist eine große Hilfe bei der Sicherung der Stadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84966] = { id = 84966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Angriff aufhalten" }
quests[84967] = { id = 84967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattenwache zerschmettert", description = "Der Kommandant der Schattenwache, Schattenfürst Al'zar, hat diesen Unterschlupf des Bunds angegriffen. Ich helfe gerade diesen verletzten Mittlern. Ich darf nicht fortgehen, oder ihre Seelenenergie wird entweichen.\n\nIch zähle auf Euch, {name}. Zieht hinaus und vernichtet Schattenfürst Al'zar. Sein Tod wird den Angriff der Schattenwache auf Tazavesh erheblich schwächen.\n\nDas Schicksal der Stadt liegt in Euren Händen.", sourceObjective = "Tötet Schattenfürst Al'zar in Tazavesh.", progress = "Geht. Wir kommen, sobald wir können.", completion = "Ohne ihren Anführer ist der Angriff der Schattenwache auf Tazavesh gescheitert! Dafür gebührt Euch mein Dank.\n\n<Er hält für einen bedeutungsschweren Moment inne.>\n\nDoch lasst Euch von diesem Sieg nicht in falscher Sicherheit wiegen. Dunklere Mächte sind im Spiel, weitaus gefährlicher als die Schattenwache.\n\nUm ihnen standzuhalten, müssen wir jeden Vorteil ausnutzen, den wir bekommen können... Selbst jene, die wir unter normalen Umständen nicht in Betracht ziehen würden.", sourceObjectiveStatus = "unverified-source-field" }
quests[84971] = { id = 84971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um Grogs willen" }
quests[84972] = { id = 84972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leere zersplittern", description = "Seid gegrüßt. Ich bin Driruj. Ich glaube, dass Ihr mir bei einem meiner Projekte helfen könntet. \n\nDas nahe gelegene Feld aus lilafarbenem Kristall birgt viel Potenzial. Das leerenerfüllte Glas lässt sich sowohl als Zauberreagenz verwenden als auch für verschiedene Handwerke einschmelzen. Ich selbst kann mich ihm nicht nähern, aber jemand wie Ihr sollte keine Probleme damit haben!\n\nBringt mir einige Proben des Leerenglases zurück, damit ich ihren Wert für zukünftige Käufer einschätzen kann.", sourceObjective = "Sammelt 6 Leerenglasproben aus den Klüften der Unwirklichkeit.", progress = "Ich bin bereit, diese Welt zu verlassen, bevor das, was von K'aresh noch übrig ist, in Stücke zerfällt. Es gibt viele mögliche Anwendungsbereiche, und dementsprechend viele potenzielle Märkte, für dieses neuartige Leerenglas. \n\nPotenzial bedeutet Gewinn, und Gewinn bedeutet, dass ich mir ein neues Leben in einer weniger volatilen Welt aufbauen kann.", completion = "Nun? Lasst mich sehen, was Ihr besorgt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84973] = { id = 84973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Partikeln und Schalen", description = "Leider war das Leerenglas zu instabil. Allerdings habe ich eine andere Idee. Ich glaube, dass ich das Glas stabilisieren kann, allerdings nur im Moment seiner Erschaffung. Zuerst brauche ich Partikel von den Wyrms außerhalb der Biokuppel, um mein Gerät anzutreiben.\n\nUnd während Ihr schon da draußen seid, jagt auch noch ein paar dieser Kroluske. Ihre Schalen können zu einem wohlschmeckenden Getränk gemahlen werden, für das in Shattrath die höchsten Preise bezahlt werden.", sourceObjective = "Sammelt 4 Dünenwyrmessenzen und 6 Kroluskschalen.", progress = "Alles kann in Profit verwandelt werden, wenn man den richtigen Markt hat. Es geht vor allem darum, seine Kunden zu kennen, und zu wissen, was sie am meisten begehren. \n\nIch bin noch immer überzeugt, dass das Leerenglas für mich am lukrativsten sein wird, aber es muss dafür robuster werden.", completion = "Oh, Ihr kehrt mit Partikeln und Schalen zurück?", sourceObjectiveStatus = "unverified-source-field" }
quests[84974] = { id = 84974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Splitter der Hoffnung", description = "Ich glaube immer noch, dass leerenerfülltes Glas mein Ticket ist, das mich hier rausbringen wird.\n\nDas Problem liegt im Herstellungsprozess selbst. Die Partikel, die Ihr mir gebracht habt, können helfen, das Glas mithilfe von Leerenenergie zu stabilisieren. Glücklicherweise gibt es genug Leerenströme an den Rändern der Glaskluft.\n\nIch habe ein Gerät mit den Partikeln aufgeladen. Ihr müsst nur noch Leerenenergie hindurch kanalisieren! Steht dort, wo ein Leerenstrom ausbrechen wird, und sammelt dann das Glas ein, das sich bildet. Ein Kinderspiel! Oh, es könnte ein wenig kitzeln...", sourceObjective = "Sammelt 20 Leerensplitter.", progress = "Es gibt viele potenzielle Anwendungsbereiche, und dementsprechend auch viele potenzielle Märkte, für neu geformtes Leerenglas. Wenn wir das richtig hinbekommen, sollte ich mich bis Ende der Woche bereits bequem in einem neuen Zuhause niederlassen können!\n\nWenn Ihr das Gerät haltet, während Ihr über einem Leerenstrom steht, sollte die Energie der Partikel helfen, stabilere Fragmente zu erzeugen.", completion = "Nun? Lasst mich sehen, was Ihr besorgt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[84985] = { id = 84985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch nichts bereit am Set", description = "Oh, {name}, bin ich froh, Euch wiederzusehen.\n\nMeine Vorgesetzten haben mich darüber informiert, dass ich nicht nur für die Gäste hier verantwortlich bin, sondern für alle, die an den Feierlichkeiten teilnehmen!\n\nUnd jetzt kommt mir zu Ohren, dass Schmucktau im Ardenwald ein neues Stück auf die Beine stellen will und nun auf Probleme stößt.\n\nKönntet Ihr dort vorbeischauen? Ich komme gerade so mit den Feierlichkeiten hier zurecht, aber dann noch was auch immer gerade in den Schattenlanden vor sich geht...", sourceObjective = "Sucht Schmucktau im Ardenwald auf.", completion = "Seid Ihr hier, um bei der Bühnenvorbereitung mitzuhelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[84993] = { id = 84993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingerangriff: Die Oase" }
quests[84994] = { id = 84994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachweis der Wirkung" }
quests[84995] = { id = 84995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bilder! Bilder von Lorenhall!" }
quests[84997] = { id = 84997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was bevorstehen könnte", description = "Danke, dass Ihr uns begleitet habt, {name}. Es ist längst überfällig, dass ich von meinem geliebten Rhonin Abschied nehme.", sourceObjective = "Wohnt Vereesas Zeremonie bei.", completion = "Uff... <Vereesa krümmt sich.>\n\nTruppen der Leere... greifen an. Wieso hier... jetzt?", sourceObjectiveStatus = "unverified-source-field" }
quests[84998] = { id = 84998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringer der Leere", description = "Geht mit... Arator. Tötet... ihren Anführer.", sourceObjective = "Tötet Leerenbringer Aqu'lir.", completion = "Der Schmerz lässt ein wenig nach, aber einen Moment brauche ich noch.", sourceObjectiveStatus = "unverified-source-field" }
quests[85001] = { id = 85001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seid gesegnet", description = "Diese Unschuldigen wollten lediglich die Ruinen säubern, doch die Kultisten schlachten sie ab. Wir müssen ihnen zu Hilfe eilen!\n\nChampion, ich bin sicher, dass wir beide das schaffen, wenn wir zusammenarbeiten.", sourceObjective = "Helft Arator, 8 Hüter von Dalaran aus den Fängen der Zwielichtklinge zu retten.", progress = "Diese armen Seelen sind ohne eigenes Verschulden in Gefahr geraten!", completion = "Ich bin nicht sicher, wieso diese Kultisten es auf meine Familie abgesehen haben, aber sie werden scheitern!", sourceObjectiveStatus = "unverified-source-field" }
quests[85002] = { id = 85002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Tazavesh", description = "Wir müssen unbedingt den Rat meiner Mutter einholen. Doch dazu müssen wir sie erst finden.\n\nSie soll zuletzt in den Großen Dunklen Weiten auf einer Welt namens K'aresh auf der Jagd gewesen sein.\n\nZu unserem Glück habe ich Khadgar in weiser Voraussicht um eine Portalschriftrolle gebeten, um direkt dorthin zu gelangen. Wir sehen uns auf der anderen Seite.", sourceObjective = "Trefft Euch mit Arator in Tazavesh, dem Verhüllten Markt in K'aresh.", completion = "Danke, dass Ihr mich begleitet habt, {name}. Ich weiß, dass ich noch viel zu lernen habe. Ich möchte nur meinem Namen gerecht werden.\n\nNun müssen wir nur noch meine Mutter auf dieser zersplitterten Welt finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85003] = { id = 85003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung der effektiven Bereitschaft", description = "Der Raumgänger wurde in den Bund geholt, um so eine gewaltsame Leerenkrise bewältigen zu können. Er sagt, Ihr seid eine Art Held oder Champion. Gut. Genau so jemanden brauchen wir.\n\nTazavesh wird von der Leere bedroht. Die Schattenwache! Sie gefährdet die Arbeit des Bundes und meinen Ruf als Administrator.", sourceObjective = "Helft den Mittlern von Tazavesh mit ihren Problemen.", completion = "Alle Probleme sind gelöst. Zumindest alle, die in meinem Buch standen und für die ich verantwortlich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[85005] = { id = 85005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein strahlender Ruf", sourceObjective = "Trefft Euch mit Mylton Wyldbraun beim Lager der Strahlen der Flamme in Heilsturz.", completion = "Wie ich sehe, habt Ihr meine Nachricht erhalten, {name}. Sehr schön! Wir können immer fähige Krieger in den Reihen der Strahlen der Flamme brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85006] = { id = 85006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jene, die wir verloren haben", description = "Ah, Wanderer! Dieser war einer der ersten Orte, an dem wir eine Reaktion auf unsere Versuche sahen, das Land zu erneuern. Wir untersuchen derzeit aktiv, warum gerade hier dieser Effekt eingetreten ist.\n\nIch möchte ein weiteres Experiment durchführen, aber dafür benötige ich zusätzliche Energiequellen. Die Seelen, die die Dünen bedecken, sind leider verloren, doch vielleicht können wir sie ein letztes Mal dienen lassen, indem wir ihre Energie nutzen.", sourceObjective = "Sammelt flackernde Essenz.", progress = "Wie ist es gelaufen?", completion = "Ah, ja. Das sollte für den nächsten Schritt genügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85007] = { id = 85007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeweiteter Bereich", description = "Ich möchte wirklich gern wissen, warum der Einfluss dieser Wiederherstellung genau dort aufgehört hat, und meine Kolleginnen und Kollegen ebenso. Wir haben einige Vorrichtungen am Rand der Dünen aufgestellt, um die Schwankungen verschiedener Energieformen zu messen.\n\nSie dürften nun lange genug dort gestanden haben, um erste Werte zu liefern. Könntet Ihr die Daten für mich abholen?", sourceObjective = "Sammelt Messdaten von den Mittlerpylonen.", progress = "Ich hoffe, die Geräte waren leicht zu finden.", completion = "Hm... Hier scheint alles völlig normal zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[85008] = { id = 85008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machenschaften der Erinnerung", description = "Nun, die Messwerte geben keinen Grund zur Sorge...\n\nAlso fahren wir mit dem nächsten Schritt meines Experiments fort. Diese Konsole hier ist das zentrale Element unseres Systems zur Erneuerung des Gebiets. Ich hoffe, dass wir mit einer ausreichend starken Ladung die Umgebung weiter stabilisieren können. Wärt Ihr so freundlich, die Energiekapseln vorzubereiten, während ich die Maschine einstelle?", sourceObjective = "Interagiert mit der Konsole.", progress = "Ja?", completion = "Faszinierend! Es hat funktioniert!\n\nWir müssen sofort einige Tests durchführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85009] = { id = 85009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jene, die wir noch retten müssen", description = "Die Geschöpfe hier scheinen in ihrer Gestalt jenen zu ähneln, die einst in der Nähe lebten, als K'aresh noch unversehrt war. Doch ihr Verhalten ist für ihre Art äußerst ungewöhnlich.\n\nIch frage mich, ob wir ihnen mit einem letzten Impuls zur vollen Manifestation verhelfen können. Nehmt den letzten Rest der Energie. Ich habe ein Gerät, mit dem Ihr sie in diese Wesen leiten könnt.", sourceObjective = "Ladet 6 flackernde Ephemera auf.", progress = "Habt Ihr unser Experiment durchgeführt?", completion = "Sie... haben sich aufgelöst? Nein, nein, nein. Das kann nicht sein!\n\nSicherlich ist etwas an meinen Berechnungen falsch! Wahrscheinlich haben wir sie gestört, anstatt ihnen zu helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[85011] = { id = 85011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo in K'aresh ist Alleria Windläufer?", description = "Während Ihr unterwegs wart, war ich so frei, mich umzuhören. Diese Mittler scheinen ja recht freundlich zu sein, aber seid gewarnt... Ein Teil der Stadt wird noch immer von einer Gruppe Astraler angegriffen, die sich die Schattenwache nennt.\n\nIch konnte einen Hinweis auf einige Händler bekommen, die meine Mutter möglicherweise vor Kurzem begegnet sind.\n\nWir sollten aufbrechen, bevor sich ihre Spur verliert.", sourceObjective = "Findet den Aufenthaltsort von Alleria Windläufer heraus, indem Ihr Euch in Tazavesh, dem Verhüllten Markt umhört.", completion = "Wenn Vereesas Vision wahr ist, muss Silbermond verteidigt werden. Die Ren'dorei werden dem Ruf folgen. Da bin ich sicher.\n\nIn der Zwischenzeit bringe ich Euch zu Alleria.", sourceObjectiveStatus = "unverified-source-field" }
quests[85013] = { id = 85013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fällmittel der Düsternisverschmolzenen" }
quests[85018] = { id = 85018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pakete der Verheißungen", description = "Ich werde keinen Moment länger warten. Ich habe eine Transportmöglichkeit außerhalb der Kuppel arrangiert, die bald ankommen sollte. \n\nTrefft Ihr mich draußen? Es gibt eine letzte Sache, um die ich Euch bitten möchte.", sourceObjective = "Sprecht mit Driruj.", progress = "Driruj ist ein Narr! Sein Hitzkopf wird irgendwann einmal seine Bandagen verbrennen. Er wird zurückkommen.", completion = "Nun? Ist er bereit, sich zu entschuldigen, und zu seiner Arbeit zurückzukehren? \n\n<Ihr gebt ihm das Säckchen mit dem Saatgut.>\n\nWas soll das sein?", sourceObjectiveStatus = "unverified-source-field" }
quests[85019] = { id = 85019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bitte eines Verstoßenen", description = "Ich habe es gespürt. Etwas ist in dieser Kuppel geschehen. Etwas... Nein, jemand...\n\n<Mein Freund/Freundin>, ich kenne weder Euren Namen noch Eure Herkunft, aber das ist es! So muss es sein!\n\nDie zerstörte Stadt Sufaad liegt südöstlich von hier. Dort lebte ich einst als Ödnisbewohner. Bitte begebt Euch dorthin und bringt meinen Szepter, mein Gebetsbuch und meine Zeremonialschale zurück. Zum Packen blieb keine Zeit, ich bin einfach nur geflohen. Die Gegenstände könnten also überall in der Stadt sein.", sourceObjective = "Bergt die Habseligkeiten von Hizfran dem Verstoßenen aus Nordsufaad.", progress = "Sobald ich meine Habseligkeiten habe, werde ich den Pfad der alten Wege wieder beschreiten können. Es ist an der Zeit, mein wahres Gelübde zu erneuern.", completion = "Ich wusste es, von dem Moment an, als ich Euch sah. Die Zeit ist reif, dass K'aresh seine Priester zurückbekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85020] = { id = 85020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut von K'aresh", description = "In alten Zeiten verwendeten wir bestimmte tief abgebaute Salze für Reinigungsprozesse und Rituale. Wie Ihr sehen könnt, ist das Abbauen nicht mehr möglich, da diese zerbrechlichen Felsen aneinanderhängen.\n\nAm Tag des Verschlingens von K'aresh trat ein noch nie zuvor gesehener Mineralstoff zu Tage. Das Blut von K'aresh ist ein blauer Mineralstoff mit einigen Vorkommen westlich von hier. Obwohl K'aresh stirbt, sollte ich die alten Traditionen bis zum Ende respektieren.\n\nBitte sammelt Vorkommen von Sandschreitern oder Adern und bringt sie zu mir.", sourceObjective = "Sammelt 20 Blutvorkommen von K'aresh.", progress = "Obwohl das Blut von K'aresh vor dem Verschlingen nicht wie andere Mineralien existiert haben mag, stammt es aus unserer Welt und sollte daher immer trotzdem im Prozess nutzbar sein.", completion = "Ja. Diese werden genügen. Ich werde sie zu feinem Pulver mahlen und sie verwenden, um die Gegenstände für mein Ritual der Rückkehr zu reinigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85021] = { id = 85021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung der Leere", description = "Nun, da Ihr mir alles gebracht habt, was ich brauche, kann das Ritual der Rückkehr beginnen.\n\nSeht, Fremder, die Gegenstände, die Ihr wiederbeschafft habt, wurden über hunderttausend Jahre in meiner Hütte aufbewahrt. Die uns umgebende Leere hinterlässt ihre Spuren auf allem, was sie berührt.\n\nDas Mahlen des Minerals hat zwar die Unreinheiten der Leere entfernt. Ich muss mich und die Gegenstände aber dennoch reinigen. Bitte helft mir bei dem Ritual. Ich erwarte keine Ablenkungen oder Probleme. Wir sind nun sehr nah dran.", sourceObjective = "Helft Hizfran dem Verstoßenen mit dem Ritual der Rückkehr.", progress = "Fast geschafft, Fremder...{name}. Das ist Euer Name, nicht wahr?", completion = "Das Ritual der Rückkehr ist vorbei, aber...\n\nHabt Ihr es gespürt?", sourceObjectiveStatus = "unverified-source-field" }
quests[85022] = { id = 85022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priester der Alten Wege", description = "{name}, ich vermute, dass eine lebende Manifestation der Leere aus mir und den Gegenständen hervorkam. Ich kann das Amt eines Priesters der alten Wege nicht mit gutem Gewissen annehmen, solange diese Manifestationen noch da draußen sind.\n\nIch habe eine letzte Bitte an Euch.\n\nFindet diese Kreaturen und tötet sie. Erst dann werde ich das Amt des Priesters wieder aufnehmen können.", sourceObjective = "Tötet 3 Manifestationen der Leere.", progress = "Ein Schritt, {name}. Ein letzter Schritt.", completion = "Ihr habt es geschafft. Nichts, was ich Euch geben könnte, ist eine ausreichende Belohnung für das, was Ihr mir gegeben habt.\n\nEndlich ergibt meine Vision Sinn, die ich vor so vielen Jahren von Euch hatte. Ihr habt mich gerettet. Meine Seele.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[85024] = { id = 85024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger mit dem Spielzeug", description = "<Abenteurer/Abenteurerin>, Maru braucht wieder Eure Hilfe.\n\nEs gibt eine dringende Angelegenheit, über die sie mit Euch sprechen möchte.", sourceObjective = "Sprecht mit Maru.", completion = "Jippie, Ihr szeit hier szum Helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[85025] = { id = 85025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation Spielzeugrettung", description = "Ein lisztiger Tieb hat meinen Freunten ihre Szpielszeuge geklaut!\n\nIhr szeit gut im Sznüffeln, oder? Könnt Ihr meinem Freunt Yennu helfen, szein gesztohlenesz Szpielszeug szu finten? Ihr fintet ihn auf ten Tracheninszeln.", sourceObjective = "Findet die verschwundenen Spielzeuge.", completion = "Ihr szeid wirklich ein Rettungszexperte für Szpielszeuge! Wer, glaubszt Ihr, hat die Szpielszeuge überhaupt geklaut?\n\nWir szollten die Hinweisze durchszehen, die Ihr gefunden habszt, um den Szuldigen zu entlarven! Kommt morgen wieder, dann können wir unsz die Beweisze anszehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85026] = { id = 85026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Legenden geschaffen werden", description = "Es gibt so vieles, über das ich Euch auf den neuesten Stand bringen muss, {name}!\n\nWo sollen wir anfangen?", sourceObjective = "Wählt eine Zeitwanderungskampagne von Chromie aus.", progress = "Oh, das ist mein liebster Pfad!", completion = "Kommt zu mir zurück, wenn Ihr wollt, dass ich Euch auf einen anderen Pfad setze!", sourceObjectiveStatus = "unverified-source-field" }
quests[85027] = { id = 85027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Das Protektorat", description = "Ich bin schon lange an den Astralen interessiert, die zum ersten Mal in Pandaria erschienen, als die Nebel sich lichteten. Eine geheimnisvolle Gruppe, die eher schweigsam ist, wenn es um ihre Vergangenheit geht... Doch möglicherweise bin ich etwas hartnäckiger als die meisten anderen, wenn es darum geht, nachzuhaken.\n\nNun denn! Wer sind diese Fremden? Was wissen wir über ihre Geschichte? Es scheint, als müssten wir sie zusammensetzen.\n\nDoch unsere Geschichte beginnt in der Scherbenwelt, wo ein Held sich einer Gruppe Astraler im Nethersturm anschloss, um ihnen bei ihrer Sache zu helfen.", sourceObjective = "Folgt Chos Weisung, um mehr über die Astralen zu erfahren.", completion = "Mit dem Sieg über Salhadaar und Dimensius schien es, als wären die größten Probleme der Astralen endlich gelöst worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85028] = { id = 85028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Die Mittler", description = "Die Astrale sind wahrhaft faszinierend, doch während meiner Studien bin ich auf ein weiteres Volk an Kreaturen gestoßen, das viele Gemeinsamkeiten mit den Astralen hat. Wir sollten uns auch über sie unterhalten... die Mittler.\n\nSie sind nomadisch, haben ein Verlangen, seltene und ungewöhnliche Antiquitäten zu sammeln, und handeln gerne.\n\nUnd doch existieren die Mittler nicht in Azeroth. Sie verweilen stattdessen in den Schattenlanden... dem Land des Todes.", sourceObjective = "Folgt Chos Weisung, um mehr über die Mittler zu erfahren.", completion = "Ich finde es überaus spannend, wie viel diese beiden Völker gemeinsam haben: Geht es Euch auch so?", sourceObjectiveStatus = "unverified-source-field" }
quests[85029] = { id = 85029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Der Raumgänger", description = "Auch wenn das Protektorat der Scherbenwelt Dimensius und Salhadaar aufhalten konnte, blieb das Astraleum bestehen. Und wie Salhadaar es wünschte, gaben sie sich der Leere hin.\n\nNicht nur das... Sie wollten die Leere selbst werden. Sie verzerrte sie, machte sie zu Schatten ihrer selbst, die von der Suche nach Macht verzehrt werden.\n\nDoch es gab einen Astralen, den Raumgänger, der sich die Macht der Leere für altruistischere Zwecke aneignen wollte. Seine Geschichte ist mit der Geschichte einer Elfe unserer Welt verwoben... Alleria Windläufer.", sourceObjective = "Folgt Chos Weisung, um mehr über Leerenastrale zu erfahren.", completion = "Die Intentionen des Raumgängers scheinen gut zu sein, doch es gibt Leute, die bis zum heutigen Tag nicht nur an ihm, sondern auch an Alleria zweifeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[85032] = { id = 85032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was noch von der Heimat übrig ist", description = "Dimensius bedroht uns erneut. Es gibt niemanden, der seine Methoden besser kennt als seine ehemalige Vorbotin, Xal'atath. Ich würde nicht sagen, dass wir ihr vertrauen können, aber wir können mit ihr zusammenarbeiten. Sie fürchtet den Zorn des alles Verschlingenden nach ihrem Verrat.\n\nWir können es uns nicht leisten, potenzielle Verbündete zurückzuweisen. Bedenkt, wie viele wir vor dem Hunger des Leerenfürsten retten können. Verschafft Euch einen Überblick über diese Stadt, die wir vier gemeinsam gerettet haben. Ich werde Alleria überzeugen.", sourceObjective = "Sprecht mit den Bewohnern von Tazavesh und Mitgliedern des Bundes.", progress = "Es wird einen Tag geben, an dem K'aresh wieder aufgebaut wird.", completion = "Dafür kämpfen wir, {name}. Wir können nur Fragmente von K'aresh retten, aber wir können verhindern, dass andere Welten unser schreckliches Schicksal teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85035] = { id = 85035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expresslieferung für den Raumgänger", description = "Tut mir leid, Eure Unterhaltung gestört zu haben, doch es war eben jene Unterhaltung, die die Aufmerksamkeit von Ve'nari auf sich gezogen hat. Sie überhört schließlich nichts... Besonders nicht, wenn ihr Name fällt.\n\nIch wurde mit einem Gegenstand entsandt, den Ihr an den Raumgänger übergeben sollt. Er ist ein Astraler, der sich im Telogrusriss aufhält. Wenn mich nichts täuscht, verweilen dort auch die \"Leerenelfen\" Eurer Welt.\n\nEs gibt keinen Grund, die beschwerliche Reise auf Euch zu nehmen, also werde ich ein Portal für Euch öffnen. Seid Ihr gewillt, ihr bei dieser Aufgabe zu helfen?", sourceObjective = "Übergebt Ve'naris Gerät an den Raumgänger im Telogrusriss.", progress = "Was hat die Schattenwache hier verloren?", completion = "Eine Lieferung für mich? Merkwürdig. Also gut, dann zeigt mal her... Und danke, dass Ihr mir geholfen habt, die Schattenwache zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[85036] = { id = 85036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veni, Vidi, Ve'nari", description = "Ein Mittler hat Euch mit diesem Gerät hergeschickt? Und zwar im Auftrag von Ve'nari?\n\nDas verheißt nichts Gutes.", sourceObjective = "Hört Euch das Gespräch mit Raumgänger an.", completion = "Der Raumgänger und Ve'nari kannten sich also? Seid Ihr Euch sicher?\n\nScheint, als wäre meine Forschung nicht unbegründet gewesen.\n\nEigentlich wollte ich Euer Wissen über die Astralen erweitern, doch stattdessen habt Ihr mein eigenes Wissen erweitert! Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[85037] = { id = 85037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles abgewickelt", description = "Es gibt nicht mehr viele Möglichkeiten. Wir stehen kurz vor dem Sieg. Seid Ihr bereit, mein Champion, Euren Eid gegen Dimensius zu erfüllen?\n\n<Xal'atath lacht leise.>\n\nGut, ich habe auch einige Versprechen einzulösen. Machen wir unsere Verteidigungsmaßnahmen gegen Dimensius auf der Plattform vor der Manaschmiede offiziell.", sourceObjective = "Sprecht mit Xal'atath, um die Reshiibänder vorzubereiten.", progress = "Was hat Xal'atath vor? Sie hatte genügend Gelegenheiten, uns zu täuschen.", completion = "Bleibt wachsam, mein Freund. Xal'ataths Spielchen haben sich noch nicht entfaltet.\n\nWir müssen auf ihren unvermeidlichen Verrat gefasst sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[85039] = { id = 85039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kompromittierte Eindämmung", description = "Irgendwie ist ein Artefakt in der Menagerie aufgebrochen und hat einen Schwarm wütender Arkanwesen freigesetzt. Sie richten Chaos an, und Chaos ist schlecht für das Projekt. Ich brauche jemanden, der die Lage unter Kontrolle bringen kann, ohne Fragen zu stellen.\n\nWenn Ihr es dorthin schafft, Euch den Weg durch die Kreaturen freikämpft und das Artefakt versiegelt... werde ich Euch reichlich danken.", sourceObjective = "Tötet Arkanwesen und versiegelt das instabile Artefakt.", progress = "Habt Ihr Eure Aufgabe erfüllt?", completion = "Ihr habt das Artefakt versiegelt? Ausgezeichnet! Die verbleibenden Kreaturen sollten sich mit der Zeit auflösen.\n\nIhr habt die Gefahr mit bemerkenswerter Geschicklichkeit gemeistert. Wie versprochen, ist hier Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[85042] = { id = 85042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Spielzeug", description = "Maru hat herausgefunden, dass jetzt eines ihrer Spielzeuge fehlt!\n\nKönnte das im Zusammenhang mit den verschwundenen Spielzeugen ihrer Freunde stehen, die Ihr schon gesucht habt?", sourceObjective = "Sprecht mit Maru.", completion = "Neeein! Mein Szpielszeug ist verszwunten!", sourceObjectiveStatus = "unverified-source-field" }
quests[85043] = { id = 85043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spielzeugdieb", description = "Mein Szpielszeug! Esz wurde gesztohlen!\n\nWir müszen herauszfinden, wer der Gauner iszt, bevor er wieder szuszlägt!", sourceObjective = "Finde den Spielzeugdieb.", completion = "Jippie! Ihr habt ALLE Szpielszeuge gefunten! Wie hat der grosze Hunti szich szo viele gesznappt?\n\nIch musz szauen, ob noch mehr von meinen Szpielszeugen in tem Haufen szind...\n\nTanke für tie Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[85047] = { id = 85047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraten in Bredouille", description = "Ich habe kürzlich von einer kleinen Gruppe von Beutebuchtbukanieren erfahren, die gleich nördlich des Festplatzes gelandet sind und ihr Lager aufgeschlagen haben.\n\nAn sich sind Piraten nicht unbedingt ein Problem, aber sie bringen oft ein Element der chaotischen Unvorhersehbarkeit mit sich. Ich weiß, dass Ihr vielbeschäftigt seid, aber würdet Ihr mal nachsehen, ob sie Hilfe brauchen?", sourceObjective = "Geht zum Lager der Beutebuchtbukaniere.", completion = "Ahoi, Landratte! Ihr seht aus, als hättet Ihr was im Schädel. Habt Ihr einen Moment Zeit, zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[85051] = { id = 85051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strandsucher", description = "Ein seltsamer mechanischer Gnom sucht den Strand hier in der Nähe nach wertvollem Metallschrott ab. Ich sorge mich um seine Sicherheit, bin aber auch fasziniert. Ich frage mich nur, was er wohl sucht!\n\nVielleicht würde er seine Funde mit Euch teilen, wenn Ihr ihn unterstützt...\n\nKönntet Ihr ihm bei der Bergung von Wertgegenständen helfen?", sourceObjective = "Helft Römms bei seiner Suche nach 24 Stücken verwertbaren Schrotts.", progress = "Habt Ihr verwertbaren Schrott gefunden? Ich nehme alles, was ich finden kann.", completion = "Er mag ein seltsamer Gnom sein, doch sein Bestreben, alte Gegenstände aufzustöbern, zu bergen und wiederzuverwerten, ist sehr löblich.", sourceObjectiveStatus = "unverified-source-field" }
quests[85052] = { id = 85052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine lukrative Gelegenheit", description = "Glückverheißende Grüße, <Außerweltler/Außerweltlerin>!\n\nIch stecke schon eine Ewigkeit an diesem Posten fest und prüfe ein Manifest nach dem anderen. Das hier ist nicht der wahre Handel. Der wahre Handel findet auf den Straßen von Tazavesh statt!\n\nEs ist nur so, dass einer meiner Kontakte aus Eurer Welt gerade Abfallfracht entladen hat. Ich habe den gesamten Vorrat gekauft. Abgelaufene Lagerverträge und Ähnliches. Aber ich würde natürlich nie ohne Genehmigung handeln.\n\nEure Hilfe wäre ein Glücksfall für meine Unternehmungen. Kann ich auf Euch zählen, {race}?", sourceObjective = "Sucht Kartellboss Xy'eolm in Tazavesh auf K'aresh auf.", completion = "Xy'vez schickt Euch? Dieser kleine Schurke traut sich nicht einmal, selbst zu mir zu kommen. Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[85053] = { id = 85053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einholen von Erlaubnissen", description = "Es gibt einen Unterschied zwischen einer Genehmigung und der Erlaubnis, in Tazavesh verkaufen zu dürfen.\n\nXy'vez ist ein lizenzierter Händler. Er kann im Einklang mit den Behörden kaufen und verkaufen, was er will. Ich bin jedoch froh, dass er seinen Platz kennt. Aber auf meinen Straßen braucht Ihr meine Erlaubnis.\n\nNicht jeder weiß das. Das Kartell Ba testet gerne mal die Grenzen. Ihr bekommt die Erlaubnis von mir, wenn Ihr ihnen eine Lektion erteilt.", sourceObjective = "Erhaltet die Erlaubnis für Schatzhüter Xy'vez in Tazavesh.", progress = "Habt Ihr getan, worum ich gebeten hatte?", completion = "Sehr gut. Xy'vez kann nun auf meinen Straßen kaufen und verkaufen, was er möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[85054] = { id = 85054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artikel der Aneignung", description = "Bringt dieses Buch zu Xy'vez. Sagt ihm, dass ich Dinare im Voraus und pünktlich erwarte. Es darf keine Unstimmigkeiten zwischen meinen Aufzeichnungen und seinen geben, habt Ihr das verstanden?\n\nBegebt Euch zum Markt und informiert ihn. Händler wie er finden für gewöhnlich rasch einen Platz für ihren Stand.\n\nDieses Vorhaben wurde von mir abgesegnet. Aber sorgt dafür, dass es rentabel bleibt, sonst sehen wir uns wieder, <Außerweltler/Außerweltlerin>.", sourceObjective = "Kehrt zu Schatzhüter Xy'vez auf dem Markt von Tazavesh auf K'aresh zurück.", progress = "Gibt es gute Neuigkeiten, Außerweltler?", completion = "Der Boss verlangt einen hohen Preis, aber es ist eine faire Forderung für ein neues Vorhaben. Wir werden entweder schnell Erfolg haben oder schnell scheitern.\n\nMachen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[85055] = { id = 85055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgelaufene Waren", description = "Nun denn, kommen wir zur Sache. Ich höre, Eure Welt ist voller Helden auf Abenteuern. Und wo es Abenteurer gibt, besteht immer Bedarf, ihre Schätze irgendwo zu verwahren. Immer.\n\nAlso habt Ihr Euch an unsereins gewandt, um sie sicher zwischen den Reichen zu lagern. Doch keiner von Euch hat den Vertrag gelesen. Wir haben diese Dienste inzwischen eingestellt und die Güter an ihre ursprünglichen Besitzer zurückgegeben.\n\nIhr und ich, {name}, wir verkaufen das, was übrig bleibt. Natürlich schwarz. Helft mir bei den Vorbereitungen.", sourceObjective = "Helft Schatzhüter Xy'vez dabei, die Leerenlagertresore für den Verkauf in Tazavesh auf K'aresh vorzubereiten.", progress = "Vor dem ersten Verkauf gibt es immer so viel vorzubereiten.", completion = "Ausgezeichnet! Das wäre erledigt. Wir können also mit dem Verkauf beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85059] = { id = 85059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Stück des Kuchens", description = "Das Spiel an dem Tisch sieht lustig aus. Skaggit will nich', dass Jack spielt, aber vielleicht könnt Ihr das ja!\n\nSchleicht Euch rein und macht einen Einsatz. Mal sehen, wer gewinnt!", sourceObjective = "Tragt zu einem Ereignis auf der Schlachtkarte der Sireneninsel bei.", progress = "Habt Ihr Euren Einsatz gemacht?", completion = "Jack wusste, dass Ihr wisst, wer gewinnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[85060] = { id = 85060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piratenspeisen und Aberglauben", description = "Smutholomäus, unser vertrauenswürdiger Smutje an Bord, ist auf See verschollen. Tragische Sache, sag ich Euch... aber für uns hier isses jetzt noch tragischer! Ohne unsere Glücksspeise, die unser Smutholomäus uns vor jeder Reise zubereitete, trauen wir uns nicht mehr raus auf See.\n\nWir ham schon versucht, aus seinem Gekritzel schlau zu werden, aber leider is' uns nur die Tinte verwischt.\n\nMein Kamerad hier schwört, dass Smutholomäus mal davon sprach, dass er nur Kopien der Rezepte mit an Bord bringt. Wenn das stimmt, müssen die Originale nach in Beutebucht sein, irgendwo in der Nähe von seinem Unterschlupf.", sourceObjective = "Helft den Beutebuchtbukanieren, Smutholomäus Glücksspeise nachzukochen.", progress = "Smutholomäus und ich haben viele lange Gespräche über Wörter und Sprachen geführt. Er war ein viel feinsinnigerer Kerl, als die meisten ihm hier zugetraut hätten.", completion = "<Die rauborstige Rosa sieht die Notizen durch.>\n\nDas sieht wie eine simple Substitutionschiffre aus. Ich brauch einen Tag oder so, um sie zu entschlüsseln, also behalte ich die Notiz erstmal und geb Euch Bescheid, wenn ich was für Euch habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[85071] = { id = 85071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenrennen", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[85075] = { id = 85075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Sturmsang", description = "Wir brauchen mehr Arten, die bei der Bestäubung helfen. Ich habe Eure Welt studiert und glaube, Eure Bienen aus dem Sturmsangtal wären am besten. Aber nicht diese Feuerexemplare. Zu gefährlich.\n\nBringt ein paar Bienen her, dann werden wir sehen, ob sie sich eignen. Und nehmt diesen Kommunikator mit, falls ich Euch kontaktieren muss.", sourceObjective = "Macht Euch ins Sturmsangtal in Kul Tiras auf, um Bienen für Ve'nari zu finden.", completion = "Irgendwelche Leute, die aus dem Nichts auftauchen, hatte ich nicht auf dem Zettel meiner erwarteten Interaktionen für heute.\n\nSei's drum, Ihr seht immerhin tüchtig aus. Vielleicht habt Ihr Interesse, mir zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[85076] = { id = 85076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles für die Biene", description = "Irgendwas reizt die Bienen hier, und ich habe den Verdacht, dass diese honiggierigen Zerfleischer dahinterstecken!\n\nBringt ein paar davon zur Strecke. Mal sehen, ob's was bringt.\n\nUnd selbst wenn nicht, tut Ihr der Welt einen Gefallen. Die Biester sind außer Rand und Band!", sourceObjective = "Tötet 10 Zerfleischer in der Hochlandplatte und Metbrauerei Mildenhall.", progress = "Die armen Bienen...", completion = "Gute Arbeit. Ich meine, es hat nicht geholfen. Die Bienen sind immer noch unruhig.\n\nAber Ihr habt die Welt ein bisschen sicherer gemacht, das ist doch auch was wert!", sourceObjectiveStatus = "unverified-source-field" }
quests[85077] = { id = 85077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klebrige Finger", description = "Sturmsang hat einige der besten und größten Bestäuber in ganz Azeroth vorzuweisen. Zumindest, wenn sie gerade nicht wütend sind. Wenn Ihr sie mitnehmen wollt, müsst Ihr erst mal versuchen, sie zu beruhigen.\n\nWie es scheint, stiehlt irgendwer ihren Honig. Versucht doch, ein bisschen Honig von diesen Honig...klumpendingern wiederzuholen.\n\nKann nicht schaden, oder? Tut mir leid, ich bin eher eine Pflanzenfreundin als Bienenexpertin. Aber ohne Bienen blüht auch nichts!", sourceObjective = "Sammelt 7 Honigkügelchen in der Metbrauerei Mildenhall.", progress = "Habt Ihr den Honig?", completion = "<Alaenra betrachtet Eure sehr klebrigen Finger.>\n\nGut gemacht! Ich... werde Euch allerdings nicht die Hand geben. Aber sehr gut gemacht!\n\nNur sind die Bienen leider immer noch sehr unruhig. Aber für den Honig finden wir später sicher noch eine Verwendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[85078] = { id = 85078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenstich", description = "Während Ihr auf Honigsuche wart, habe ich einige der kleinen Bienenstöcke untersucht. Sie haben scheinbar alle Schäden erlitten.\n\nWir sollten der Sache nachgehen. Vielleicht ist das die Ursache für ihr aggressives Verhalten.", sourceObjective = "Untersucht vier Bienenstöcke.", progress = "Was könnte dazu geführt haben, dass etwas so viele Bienenstöcke zerstört?", completion = "Oh nein! Die arme Bienenkönigin! Wir müssen sie retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[85079] = { id = 85079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenschlaf", description = "Wir müssen uns irgendwie um diese Stockwächter kümmern, wenn wir uns hier umsehen wollen.\n\nIch hoffe bloß, wir müssen sie nicht töten.", sourceObjective = "Besänftigt oder tötet 5 Stockwächter.", progress = "Wir müssen versuchen, dass so viele Bienen wie möglich überleben.", completion = "Bienen sind Superbestäuber! Es ist höchst bedauerlich, dass sie gerade so mörderisch sind. Normalerweise sind sie ziemlich ruhig!", sourceObjectiveStatus = "unverified-source-field" }
quests[85080] = { id = 85080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summender Sauger", description = "Wenn wir die kleineren Bienen retten, können sie sich dem Bienenvolk der Königin anschließen. Ich wünschte nur, wir hätten eine Möglichkeit, sie zu fangen oder zu transportieren.\n\nFällt Euch etwas ein? Vielleicht hat diese Freundin von Euch etwas?\n\nWenn Ihr größeren Bienen begegnet... fürchte ich, es ist zu spät für sie. Tut, was getan werden muss.", sourceObjective = "Holt den Animasauger und saugt damit 15 Honigbienen ein.", progress = "Habt Ihr die Bienen gerettet?", completion = "Das war eine extrem ungewöhnliche Methode, um Bienen zu fangen. Aber sie hatte Erfolg!", sourceObjectiveStatus = "unverified-source-field" }
quests[85081] = { id = 85081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honig im Topf", description = "Wir müssen uns etwas ausdenken, um die Königin hervorzulocken, damit wir sie wegbringen können.\n\nAh! Der Honig, den Ihr vorhin gesammelt habt! Stellt ihn hin, lockt sie hervor und fangt sie dann in diesem Glas mit Löchern.\n\nIhr habt doch gesagt, Ihr braucht Bienen, nicht? Ich denke, diese wäre ein perfektes Exemplar.", sourceObjective = "Stellt den Honigtopf hin und lockt die Bienenkönigin hervor, um sie zu retten.", progress = "Wenn wir sie in Sicherheit bringen und ein Teil ihres Bienenvolks folgt, können sie ihren Bienenstock wieder aufbauen.", completion = "Wir haben sie gerettet!\n\nDann bringen wir sie jetzt nach... K'aresh, richtig? Immer schön, eine neue Ecke von Azeroth zu entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[85082] = { id = 85082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach K'aresh", description = "Wir haben die Königin gerettet und offenbar auch einige Bienen nach K'aresh geschickt.\n\nAber... wie kommen wir jetzt dorthin?", sourceObjective = "Kehrt zur Oase von K'aresh zurück.", completion = "Glückwunsch. Ihr habt die Bienen hergebracht, hat ja auch lang genug gedauert. Sie befinden sich im Atrium.\n\nSobald die Bienenkönigin ankommt, können wir mit unserer Forschung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85083] = { id = 85083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzgelb-Foto", description = "Die Bienen scheinen sich in dieser neuen Umgebung gut eingelebt zu haben. Sie fangen sogar schon an, die Pflanzen hier zu bestäuben.\n\nWir sollten es dokumentieren. Es ist schließlich keine Wissenschaft, wenn man nicht alles notiert. Ihr findet die Bienen zumeist um die Pflanzen herum.", sourceObjective = "Dokumentiert 10 Honigbienen.", completion = "Habt Ihr mal überlegt, selbst in die Forschung zu gehen? Ihr habt echt ein Händchen dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[85084] = { id = 85084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenstark", description = "Es wird ein Weilchen dauern, bis sich der Bienenstock erholt hat und alles wieder summt und brummt. Gerade mangelt es auch an Honig.\n\nZum Glück habt Ihr in Sturmsang reichlich Honig gesammelt! Würdet Ihr die Königin damit füttern?", sourceObjective = "Füttert die Bienenkönigin.", progress = "Ich glaube, den Bienen wird es hier gutgehen.", completion = "Seht sie nur an. Sie ist so glücklich, dass sie sich keine Sorgen mehr um diese grässlichen Todesbienen machen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[85085] = { id = 85085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter aus Lorenhall" }
quests[85088] = { id = 85088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hauptveranstaltung" }
quests[85096] = { id = 85096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketenrennen - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
