quests[85109] = { id = 85109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen beim Bund von K'aresh", description = "Euer Beitrag zum Wohle K'areshs wird nie vergessen, <Reisender/Reisende>. Wir sind Euch zutiefst dankbar.\n\nAls Zeichen unserer Dankbarkeit haben wir ein Geschenk für Euch vorbereitet. Besucht Om'sirik in Tazavesh. Er wird dafür sorgen, dass Ihr es erhaltet.", sourceObjective = "Sprecht mit Om'sirik in Tazavesh.", completion = "Vielen Dank, Reisender. Möge es Euch gut dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85113] = { id = 85113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spezialauftrag: Aufziehender Sturm", sourceObjective = "Ich wusste, Ihr würdet uns beschützen!", sourceObjectiveStatus = "unverified-source-field" }
quests[85151] = { id = 85151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In ihrem Schatten", description = "Ihr beide seid in die Falle getappt, die ich Schattenfürst Vesheen gestellt habe. Ich muss wissen, wie seine Befehle von Salhadaar lauten und was er über Xal'ataths Pläne weiß.\n\nJetzt werden wir drei uns in dieses Lager schleichen und schauen, was wir finden können. Wir sind nicht zum Kämpfen hier, sondern nur zur Aufklärung. Er soll nicht merken, dass ich ihm auf der Spur bin.", sourceObjective = "Schleicht mit Alleria durch das Lager in Laacunas Bruch, um Hinweise auf Schattenfürst Vesheen zu finden.", completion = "Da wir nun wissen, wohin er unterwegs ist, brauche ich eine weitere Falle. Ein Käfig wird diesmal für mein Vorhaben ausreichen.\n\nUnd ich kenne genau die richtige Person, die uns einen beschaffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[85155] = { id = 85155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr noch einen über?", description = "Da wir nun wissen, wo sich Vesheen aufhält, brauche ich einen Käfig, in den ich ihn stecken kann, um Antworten zu bekommen. Und ich kenne genau die richtige Person, die uns einen besorgen wird.\n\nVe'nari.\n\nIhr findet sie in der Biokuppel namens Oase. Sie befindet sich auf der Insel im Osten. Tut, was Ihr tun müsst, und akzeptiert kein Nein als Antwort, {name}.", sourceObjective = "Reist zur Oase und überzeugt Ve'nari, Euch einen Käfig zu besorgen.", completion = "{name}, schön, Euch wiederzusehen. Was führt Euch in unsere majestätische – und nicht zu vergessen sehr teure – Oase?\n\nWollt Ihr Ärger aus dem Weg gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[85174] = { id = 85174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raus wagen", description = "Ihr habt alle gesehen, wozu Gallywix imstande ist. Diese Waffen, dieses Schwarzblut... wir müssen seine Quellen trockenlegen. Revilgaz, Ihr müsst ihre Lieferungen aus Eurem Hauptquartier stoppen. Und Grimla, Venture Company muss involviert sein, sonst wäre Nikki die Macherin nicht so gut bewaffnet. Teilt Euch auf.\n\n{name}, Euch brauch ich bei mir. Ich kenne einen Reporter, Dirk. Sprecht im Hintertürpark mit ihm. Um diese Stadt zu gewinnen, brauchen wir das Volk auf unserer Seite. Ich komme gleich nach.", sourceObjective = "Sprecht mit Dirk Schmierhändler im Hintertürpark.", completion = "Da draußen herrscht das reine Chaos! Aber wenn Gazlowe einen Plan hat, setze ich auf ihn!", sourceObjectiveStatus = "unverified-source-field" }
quests[85185] = { id = 85185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die auch noch", description = "In den Ruinen von Nordsufaad gibt es eine Vielzahl gestohlener Artefakte, die zwar kleiner, aber dennoch bedeutend sind. Wenn Ihr schon mal da seid, könntet Ihr sie doch auch gleich für mich bergen.\n\nIch werde dafür sorgen, dass die Transaktion Eure Zeit wert ist.\n\nIch hoffe, dass dies nicht unter Eurer Würde ist... solange die Bezahlung stimmt.", sourceObjective = "Bergt 6 geringe Artefakte der K'areshi von Ödnisbewohnern in Nordsufaad.", progress = "Diese geringeren Artefakte können ebenfalls von großer Wichtigkeit sein. Für die K'areshi, natürlich.", completion = "Was wären wir nur ohne unsere Geschichte und Kultur?\n\nIch werde Euch nun für Euren großzügigen Beitrag zur Bereicherung der K'areshi – und natürlich meiner selbst – entlohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85186] = { id = 85186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Käfig für Alleria", description = "Ich habe einfach eine Schwäche für Intrigen. Bitte geht schnell zurück und lasst mich wissen, wie sich die Dinge mit diesem neuen Leutnant der Schattenwache entwickeln.\n\nVielleicht statte ich Euch sogar einfach einen Besuch ab.\n\nIch bin sicher, dass Alleria diesmal all ihre Antworten erhält...", sourceObjective = "Überbringt Alleria in Shan'dorah Ve'naris Paket.", progress = "Habt ihr den Käfig? Ich hoffe, dass Ve'nari Euch nicht völlig ausgenutzt hat.\n\nBei ihr ist nichts umsonst. Gar nichts.", completion = "Man kann von ihr sagen, was man will... Ve'nari denkt an alles.\n\nVesheen in diesen Käfig zu teleportieren, wird die Sache deutlich vereinfachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85189] = { id = 85189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Tag am Gericht", description = "Wieder eine Reihe von verschiedenen und rechtlich fragwürdigen Aufgaben erledigt, {name}! Ihr solltet wirklich in Betracht ziehen, in diesem Beruf Vollzeit zu arbeiten... was auch immer das genau bedeutet.\n\nIch hole die Unterschriften der Gnome und treffe Euch dann in meinem Büro.\n\nNormalerweise würde ich Euch ja mitnehmen, aber ich muss erst noch eine persönliche Besorgung machen. Ihr werdet schon sehen.", sourceObjective = "Trefft Marty Rennraser in seinem Büro in Bruchbudenhügel.", completion = "Wir befinden uns jetzt auf der Zielgeraden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85190] = { id = 85190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Staub legt sich", description = "Ich bin überrascht, dass Shaw persönlich aufgetaucht ist. Ich dachte, er würde einen Agenten schicken oder so, aber... vielleicht sollte ich anfangen, mehr von den Leuten zu erwarten.\n\nIch habe dafür gesorgt, dass alles für Renzik erledigt wird. Dass er den Respekt bekommt, den er verdient. Ich habe lange gebraucht, um diese Truhe zu bauen. Viele kleine Werkzeuge. Ich bin solche Detailarbeiten nicht gewohnt, aber ich habe es ganz gut hinbekommen.\n\nIch bin sicher, er könnte das Schloss immer noch knacken, aber...\n\n<Gazlowe lächelt traurig.>\n\nSchicken wir ihn zurück nach Sturmwind, ja?", sourceObjective = "Sprecht mit Gazlowe, um Renziks Asche zu Mathias Shaw zurückzubringen.", completion = "Ich entschuldige mich für den plötzlichen Szenenwechsel, aber es ist wichtig, dass Ihr das seht und nicht nur hört.", sourceObjectiveStatus = "unverified-source-field" }
quests[85191] = { id = 85191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnitt für Schnitt", description = "Renzik war einer meiner besten Agenten. Aber mehr als das war er ein Freund.\n\nEr war kein Agent der Krone von Sturmwind, der widerwillig eine Mission in Lorenhall erfüllte. Er arbeitete für Sturmwind, aber er liebte Lorenhall.\n\nSein Volk war seine Heimat. Nicht wir.\n\nHelft mir, ein paar von Renziks Sachen einzusammeln, die er hiergelassen hat. Sie sollten mit ihm nach Lorenhall zurückkehren.", sourceObjective = "Sammelt Renziks Habseligkeiten rund um den Leuchtturm von Westfall ein.", progress = "Renzik hat sich mir nie ganz geöffnet, aber ich konnte erahnen, was ich wissen wollte.", completion = "Renzik hat Sturmwind und das, wofür wir standen, bewundert, aber Lorenhall hat er immer am meisten geliebt.\n\nEs ist mir wichtig, dass Ihr zwei das wisst.", sourceObjectiveStatus = "unverified-source-field" }
quests[85192] = { id = 85192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Renzik würde wollen, dass seine Asche nach Lorenhall zurückgebracht wird. Da bin ich mir sicher, und ich möchte meinem Freund einen letzten Gefallen tun und dafür sorgen.\n\nBestimmt würde ihm das viel besser gefallen, als weit weg von seinem Volk auf dem Friedhof von Sturmwind unter einer Marmorplatte verstaut zu werden.\n\nGehen wir, {name}.", sourceObjective = "Trefft Gazlowe und Mathias Shaw auf der oberen Treppe des Schrottladens in Lorenhall.", progress = "Zu wissen, dass er Lorenhall immer als sein Zuhause betrachtet hat...\n\nDas ist schon etwas. Ich hätte noch viel mehr von ihm lernen können.", completion = "Renzik ist jetzt zu Hause.\n\nWir sorgen dafür, dass es ihm nie wieder weggenommen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[85195] = { id = 85195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piratenküche", description = "Hier sind die entschlüsselten Notizen von Smutholomäus. Sie sehen immer noch ein wenig seltsam aus, aber ich bin sicher, dass ich sie richtig dekodiert habe.\n\nIch kann Euch immerhin sagen, wie viel Ihr von allem jeweils braucht, aber offenbar hat er sich eigene Bezeichnungen für die Zutaten ausgedacht, also... viel Glück!", sourceObjective = "Nutzt Rosas übersetzte Notizen für das Fröhliche Festmahl, um die Zutaten zu finden.", progress = "Keine Sorge, wir sind ein geduldiger Haufen.", completion = "Ich glaub mein Schwein pfeift, Ihr habt es wirklich geschafft! Jetzt können wir unser Festmahl kochen und wieder nach Hause segeln.\n\nVielen Dank auch!", sourceObjectiveStatus = "unverified-source-field" }
quests[85196] = { id = 85196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Markiert und portiert", description = "Vesheen befindet sich in den Ruinen von Khiyed im Norden. Dieser Narr hält sich für ach so schlau, aber er wird bald merken, dass er sich überschätzt hat.\n\nMacht ihn mürbe und platziert dann Ve'naris Marker auf ihm. Er wird ihn direkt in den Käfig hier teleportieren.\n\nIch bleibe hier und stelle sicher, dass der Käfig auch funktioniert. Beeilt Euch, {name}, bevor er merkt, dass wir ihm auf den Fersen sind!", sourceObjective = "Schwächt Schattenfürst Vesheen und platziert dann Ve'naris Portationsmarker auf ihm, um ihn in Allerias Käfig zu teleportieren.", progress = "Er wird mir alles erzählen. Für halbherzige Maßnahmen steht zu viel auf dem Spiel.", completion = "Das habt Ihr gut gemacht. Dieser Schattenwachenabschaum wird mir alles erzählen, was ich wissen muss.\n\nSonst...", sourceObjectiveStatus = "unverified-source-field" }
quests[85208] = { id = 85208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Piratenschreiben", description = "Das seid Ihr ja, {name}. Jemand namens rauborstige Rosa möchte Euch in Beutebucht treffen.", sourceObjective = "Holt Euch die Notizen von der rauborstigen Rosa in Beutebucht.", completion = "Ich hab mir größte Mühe mit den Notizen gegeben. Ich hoffe, sie helfen Euch weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[85212] = { id = 85212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leerentest der Willenskraft", description = "Das wird gefährlich. Ich will die Leere nutzen, um seinen Willen zu brechen und seinem Geist so viele Informationen wie möglich zu entlocken.\n\n{name}, haltet Euch bereit. Zuerst bereiten wir ein paar Ritualvorrichtungen vor. Wartet dann auf meine Instruktionen.\n\nEin falscher Schritt könnte unser Ende bedeuten.", sourceObjective = "Unterstützt Alleria bei ihrem Leerenkampf, um Schattenfürst Vesheens Willen zu brechen.", progress = "Unser Krieg gegen die Leere wird wohl niemals enden.", completion = "Meine Mutter hat viel geopfert, als sie Vesheen getötet hat. Ich bin sicher, dass sie ihm mehr Informationen hätte entlocken können.\n\nVielleicht war ich zu hart zu ihr.\n\nJetzt müssen wir entscheiden, wie wir weiter vorgehen. Ich hoffe, Ihr seid wieder mit dabei, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85229] = { id = 85229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauner, gruppiert Euch!", description = "Hört, hört! Seht her! Kommt alle nach Dornogal!\n\nZusätzlich zur gewohnten Auswahl an mächtiger Ausrüstung, die am Rivalentor angeboten wird, können aufstrebende Kämpfer und erfahrene Gladiatoren auch Wappenmarken kaufen, die zur Herstellung von Ausrüstung verwendet werden können, die in Arenen und auf Schlachtfeldern zugelassen ist!\n\nReicht diese Broschüre bei Hotharn ein, um ein paar davon zu erhalten - kostenlos, aufs Haus!\n\n- Aisha", sourceObjective = "Gebt die Broschüre bei Hotharn am Rivalentor in Dornogal ab.", completion = "Ah, ich hatte mich schon gefragt, wann die ersten eifrigen Kämpfer auftauchen werden. \n\nHier, nehmt das, wie versprochen. Benutzt sie, wenn Ihr Handwerksaufträge einreicht oder Eure eigene Ausrüstung herstellt. Das Ergebnis wird genauso mächtig sein wie das, was Lalandi da drüben verkauft, aber diese Teile sind großartig, wenn Ihr etwas Individuelles möchtet, das auf Eure Bedürfnisse abgestimmt ist. Wenn Ihr mehr braucht, wisst Ihr, wo Ihr mich findet.\n\nFragen? Hebt sie Euch für die Schmiedegründe auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[85238] = { id = 85238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fremde Schritte auf den Stufen", description = "Bitte! Wir müssen die Naakroaner aufhalten. Drei von uns wurden vom Kartell Om geschickt, um eine Forschungsmaschine zu installieren. Sie sollte nur dazu dienen, ausgestorbene Pflanzen zu erforschen. Zuerst waren die Ödnisbewohner höflich, sogar neugierig. Bis wir gehen wollten.\n\nSie zwangen uns, die Maschine umzubauen. Om'musa weigerte sich, also töteten sie ihn. Om'baladh und ich gehorchten. Wir hätten uns auch weigern sollen.\n\nAls wir fertig waren, wurden die Ödnisbewohner nachlässig. Om'baladh sagte, ich solle fliehen, und das tat ich. Er war direkt hinter mir. Bitte findet ihn.", sourceObjective = "Findet Om'baladh.", completion = "Ich habe ihn fallen hören. Ich hätte anhalten sollen. Stattdessen bin ich einfach weitergelaufen.\n\nWir müssen das in Ordnung bringen. Wir haben die Maschine für die Ödnisbewohner in eine Waffe verwandelt. Sie wird nicht helfen, das Land zu verjüngen. Sie wird alles ausradieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[85239] = { id = 85239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neues Verschlingen", description = "Das ist kein Tempel mehr, sondern ein Schlachthaus. Sie reißen den Gefangenen die Seelen heraus, um ihre Rituale durchzuführen. Im Moment speisen sie unsere Maschine mit gestohlener Energie. Ich glaube, ich weiß auch, warum.\n\nMit den Änderungen, die wir vorgenommen haben, wird eine Überladung des Geräts mit arkaner Energie eine massive Rückkopplungsschleife erzeugen. Das wird unsere Technomantie auf K'aresh stören. Die Biokuppeln werden versagen. Tazavesh wird wehrlos sein. Wir werden nur noch ein weiteres Festmahl für die Naakroaner. Wenn Ihr ihre Rituale unterbrechen könnt, gewinnen wir Zeit.", sourceObjective = "Unterbrecht die naakroanischen Rituale.", progress = "Haltet die Rituale auf. Beendet das Leiden der Gefangenen.", completion = "Das wird sie zwar verlangsamen, aber ich befürchte, es reicht nicht aus. Wir müssen dem ein Ende setzen, bevor sie all unsere Arbeit zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[85240] = { id = 85240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur der Hunger bleibt", sourceObjective = "Tötet naakroanische Ödnisbewohner.", completion = "Selbst wenn wir hier scheitern, könnte dies unseren Verteidigern eine Chance geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[85241] = { id = 85241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einst stolzer Priester", description = "Ihr Anführer leitet die letzte Ritualstätte: Issam der Zerreißer... Ich habe gesehen, wie er seinem Namen alle Ehre macht. Wenn er unsere Echomaschine gegen uns wendet, werden er und seine Anhänger alles niederreißen. Wir alle würden dann Opfer ihres abwesenden \"Gottes\" sein.\n\nTötet ihn und beendet sein Ritual. Wir dürfen kein zweites Verschlingen zulassen.", sourceObjective = "Tötet Issam den Zerreißer.", completion = "Nein. Er ist tot. Warum hat es nicht aufgehört? Es wird stattdessen immer stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[85242] = { id = 85242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saisonale Erfrischung", description = "Wir entdecken immer mehr in den Tiefen!\n\nBringen wir Euch aber erstmal auf den neuesten Stand mit dem, was wir gefunden haben.\n\nDann muss ich Euch noch etwas Besorgniserregendes mitteilen.", sourceObjective = "Erfahrt mehr über Saison 2 der Tiefen in den Tiefenforscherdokumenten und kauft Euch dann Vorräte bei Reno Jackson und Sir Finley Mrrgglton.", completion = "Seid Ihr bereit?\n\nIch muss Euch nämlich von etwas berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[85243] = { id = 85243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich will meinen Hut zurück", description = "Vielleicht ist Euch an mir eine Veränderung aufgefallen.\n\nEin Goblin hat mir meinen Hut geklaut! Und noch dazu all unsere gesammelten Schätze!\n\nIch erzähl' Euch, wie es passiert ist.", sourceObjective = "Hört Euch Branns Geschichte an und erfahrt, wie er seine Schätze und seinen Hut verloren hat.", completion = "Jetzt kennt Ihr die ganze Geschichte.\n\nAber immerhin hab' ich das entscheidende Teil seines Luftschiffs mitgeh'n lassen.\n\nDa habt Ihr es! Ich habe wichtigere Dinge zu erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85244] = { id = 85244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg über den Lorenboss", description = "Dieser verfluchte \"Lorenboss\" hat mir meinen Hut gestohl'n! Und noch dazu unsere gesammelten Kuriositäten.\n\nHöchste Zeit, es ihm heimzuzahl'n. Wir müssen aber noch stärker werden, bevor wir ihn stellen können.\n\nSobald Ihr bereit seid... ich weiß, dass er sich irgendwo in Lorenhall aufhält.\n\nIch komme gleich nach!", sourceObjective = "Erhöht Eure Gegenstandsstufe, um den Lorenboss in seiner Tiefe der Stufe 8 innerhalb von Lorenhall herauszufordern.", completion = "Wir haben's geschafft! Hah!\n\nJetzt wissen alle, dass sie sich besser nicht mit uns anlegen sollten!\n\nUnd niemand wird sich mehr trau'n, mir meinen Hut zu stehlen!\n\nAh... wie gut, dass ich ihn zurückhabe.\n\nHier. Nehmt meinen Ersatzhut. Ihn tragen zu müssen, während der andere weg war, passte mir gar nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[85249] = { id = 85249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testbiene", description = "Ich sende Euren... Gast... ins Atrium, um sich um die Bienen zu kümmern.\n\nIhr solltet nach ihr sehen. Sie braucht zweifellos Hilfe.", sourceObjective = "Sucht Botanikerin Alaenra im Atrium auf.", completion = "Schön Euch wiederzusehen, {name}! Seid Ihr gekommen, um zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[85252] = { id = 85252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Kinder des Blutes", description = "Die Blutelfen der Östlichen Königreiche führen jenen Namen erst seit wenigen Jahren. Einst waren sie bekannt als Hochgeborene oder Hochelfen, doch das ist längst vergangen. Man möchte meinen, es sei eine Geschichte voller Hoffnung, doch in Wahrheit spricht der Name von jenen, die in schier unvorstellbarer Zahl gefallen sind und ihre Leben verloren haben.\n\nDie Blutelfen, oder Sin'dorei, werden jenen Verlust niemals vergessen. So lasst auch uns ihrer gedenken.", sourceObjective = "Trotz allem, was sie erlebt haben, stellen sich die Blutelfen weiterhin dem Unglück. Gemeinsam halten sie jedem stand, der ihr Volk oder den Sonnenbrunnen, der den Eckpfeiler ihrer Kultur bildet, bedroht.", sourceObjectiveStatus = "unverified-source-field" }
quests[85254] = { id = 85254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrensuche: Kinder der Leere", description = "Die Leerenelfen... so seltsam. Es gibt kaum einen Unterschied zwischen einem Leerenelfen und einem Blutelfen, abgesehen davon, welcher Kraft sie sich verschrieben haben. Doch für ihre ehemaligen Verwandten sind sie ein Gräuel. Sie gelten überhaupt nicht mehr als Blutelfen und sind in ihrer früheren Heimat nicht mehr willkommen.\n\nLasst uns untersuchen, wie und warum es dazu kam.", sourceObjective = "Wir wissen nur wenig über die Leere, doch eins ist klar: Sie beherrschen zu wollen, ist vergeblich. Und doch gibt es jene, die stark genug sind, es zu versuchen, und vielleicht sind wir zu streng mit ihnen, weil sie sich die Mühe machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85255] = { id = 85255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenbetäubung", description = "Ich denke, wir sollten alles vorbereiten, um die Bienen in die Oase umzusiedeln. Ich würde sie gern markieren, damit wir den Bienenstock im Auge behalten können.\n\nLeider scheinen Bienen ungern lange genug still zu sitzen. Es bleibt uns also nichts übrig, als sie ruhigzustellen, bevor wir sie markieren können. Die Königin habe ich schon markiert. Würdet Ihr die Honigbienen markieren?", sourceObjective = "Besänftigt und markiert 10 Bienen in der Biokuppel: Primus in K'aresh.", completion = "Ah, danke! Ich hoffe, Ihr wurdet nicht gestochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[85256] = { id = 85256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich was mit Pflanzen", description = "Die Bienen sind wohlauf und scheinen sich gut mit der örtlichen Fauna zu vertragen. Aber was ist mit der Flora?\n\nIch habe einige Pflanzenproben aus der Oase. Würdet Ihr Proben aus dieser Kuppel sammeln, damit ich sie vergleichen kann?", sourceObjective = "Sammelt 10 abgeschnittene Pflanzen aus K'aresh.", progress = "Ich freue mich riesig, endlich wieder mit Pflanzen zu arbeiten. Fühlt sich an, als wäre es schon bienionen Jahre her. Versteht Ihr? BIENionen?", completion = "Hervorragend! Die Bienen und Pflanzen vertragen sich vortrefflich. Das heißt, sie können nun in die Oase übersiedeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[85257] = { id = 85257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenkuppel Primus", description = "Gut. Bringen wir diese Bienen in die Biokuppel: Primus für die nächsten Tests.", sourceObjective = "Sucht Botanikerin Alaenra in der Biokuppel: Primus auf.", completion = "Wenn ich eine Biene wäre, dann die Bienenkönigin.", sourceObjectiveStatus = "unverified-source-field" }
quests[85258] = { id = 85258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honigmomente", description = "Der Bienenstock hat sich gut eingelebt. Ich würde aber gern eine kurze Honigprobe durchführen. Der Pollen dieser Pflanzen ist ziemlich anders, das sollte sich auch im Honig bemerkbar machen. Wir müssen sicherstellen, dass er für den Bienenstock geeignet ist.\n\nBasierend auf den Experimenten in den anderen Kuppeln sollte alles in Ordnung sein. Aber lieber auf Nummer sicher gehen, oder?", sourceObjective = "Sammelt 8 Honigwaben und streichelt dann die Bienenkönigin in der Oase.", progress = "Habt Ihr die Honigwabe eingesammelt?", completion = "Ich analysiere ihn gründlich, um sicherzustellen, dass alles in Ordnung ist. Vielen Dank.\n\nAlaenra erwähnte eine weitere Aufgabe, falls Ihr Zeit habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85259] = { id = 85259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wedeltanz", description = "Alaenra trug mir auf, Euch folgende Botschaft zu übermitteln:\n\n\"Hey Om'talad, ich werde für die Bienen tanzen, damit sie wissen, wo die neuen Blumen sind. Könntet Ihr {name} darum bitten, das gleiche zu tun?\"\n\nEtwas seltsam, gewiss, doch fühlt Euch frei, nach Herzenslust... zu tollen.", sourceObjective = "Tanzt für die Bienen in der Oase.", completion = "Habt Ihr fleißig wie die Bienen getanzt? {name}, Ihr wart klasse. Das hilft den Bienen und der Oase, zu florieren. Mehr Bienen, die wissen, wo mehr Pflanzen sind? Was soll da schiefgehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[85260] = { id = 85260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überarbeitete Bienchen", description = "Ich habe gerade ein paar Bienen gesehen, die auf den Boden geplumpst sind. Ich glaube, sie haben sich einfach überarbeitet, um zu den neuen Pflanzen zu gelangen.\n\nSie erholen sich bestimmt. Sie sind nur müde. Würdet Ihr mir helfen, sie aufzuheben und zurück zum Bienenstock zu bringen?", sourceObjective = "Hebt 10 überarbeitete Honigbienen auf und bringt sie zum Bienenstock zurück.", progress = "Die armen Bienen! Geht behutsam mit ihnen um.", completion = "Alle Bienen anwesend. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[85261] = { id = 85261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bienenstockfotos", description = "Ah, da seid Ihr ja. Zeit, alles zu dokumentieren!\n\nWir müssen festhalten, wie es den Bienen in der Oase geht. Ich habe den Papierkram bereits ausgefüllt. Vielleicht könnt Ihr mir einige Bilder von den Bienen in Aktion besorgen?", sourceObjective = "Dokumentiert 10 Honigbienen und die Bienenkönigin.", progress = "Habt Ihr ein paar gute Aufnahmen gemacht?", completion = "Ihr habt das mit der Fotografie echt raus. Schaut Euch nur die Komposition dieses Bildes an!\n\nWir brauchen keine Fotos auf dem Niveau von Katalogisierer Wulferd... aber ich freue mich natürlich trotzdem.", sourceObjectiveStatus = "unverified-source-field" }
quests[85262] = { id = 85262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die königliche Prozession", description = "Hmm, Eure Fotos überzeugen mich, dass der Bienenstock bereit ist auszuschwärmen!\n\nEs ist das ultimative Ziel eines jeden Bienenstocks, eine neue Königin zu gebären und einen neuen Bienenstock zu gründen. Das bedeutet, dass unsere Königin an einen neuen Ort gebracht werden muss, doch wir haben ja genug Platz in der Biokuppel, nicht wahr?\n\nKönnt Ihr der Königin helfen, einen neuen Ort zu finden?", sourceObjective = "Helft der Bienenkönigin dabei, einen neuen Ort für ihren Bienenstock zu finden.", progress = "Ist die alte Bienenkönigin nun sicher eingezogen?", completion = "Hervorragend - unsere Königin ist ganz schön groß geworden!", sourceObjectiveStatus = "unverified-source-field" }
quests[85263] = { id = 85263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bummkugel" }
quests[85268] = { id = 85268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochdruck-Rrreinigungssimulator" }
quests[85269] = { id = 85269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bummballon" }
quests[85270] = { id = 85270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiskalt" }
quests[85383] = { id = 85383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angewandte Mixologie", description = "Gestattet mir, mich vorzustellen, <Reisender/Reisende>. Man kennt mich als Ba'kril.\n\nWie Ihr wisst, hat mein Volk einen anderen Trinkgeschmack als das Eure. Ich habe einen einfachen Vorschlag: Helft mir dabei, ein neues Energiegetränk zu brauen, und ich werde Euch erlauben, es kostenlos zu benutzen.\n\nEs wird Euch definitiv zu einem Helden unter Helden machen. Ist das nicht ein angemessener Preis für das Risiko?\n\nIch habe mehrere potente Energiequellen erworben. Speist sie in den Beerensaft-Cocktail ein. Dann erfahren wir, wie potent wir das Getränk machen können.", sourceObjective = "Braut ein Energiegetränk, in das verschiedene Energiequellen eingespeist sind.", progress = "Ich schwöre es Euch bei der Seele von K'aresh, Reisender. Wir werden das feinste und stärkste Gebräu erschaffen, das die Welt je gesehen hat. Damit werdet Ihr die Macht von zehn Verschlingern haben!\n\n<Ba'kril murrt etwas über Tazaveshs Führungsqualitäten vor sich hin.>\n\nSelbstverständlich werde ich daran aber auch ein wenig Geld verdienen.", completion = "Unfassbar! Es hat funktioniert und wir wurden nicht in unzählige kleine Fetzen gesprengt. Ich hoffe in der Tat, dass sich diese Formel nicht nur für Euch, sondern für die Zukunft von K'aresh als nützlich erweisen wird.\n\nJetzt zu Phase zwei... Tests und Marktforschung.", sourceObjectiveStatus = "unverified-source-field" }
quests[85384] = { id = 85384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marktforschung", description = "Da ich niemals an Eurem Erfolg gezweifelt habe, habe ich mir die Freiheit genommen, bereits mit den nächsten Vorbereitungen anzufangen.\n\nIch habe uns ein paar Freiwillige organisiert. Ich will unser neues Energiegetränk in Aktion sehen, bevor Ihr davon kostet, {name}. Darf ich Euch {name} nennen? Natürlich darf ich das. Wir sind jetzt Geschäftspartner.\n\nIhr findet die Freiwilligen auf den Hochterrassen der Stadt. Tazavesh hat viele komfortable Bereiche wie diese für Gäste wie Euch zu bieten.", sourceObjective = "Sprecht mit den Freiwilligen, um das neue Energiegetränk zu testen.", progress = "Wir beide werden aus diesem Unterfangen definitiv Profit schlagen, {name}. Unabhängig vom Ausgang.", completion = "Die Stadt zerstören?! Ihr müsst mir schnell und unauffällig helfen, diese... *ähm* Situation in Ordnung zu bringen, Partner.\n\nBin ich zu dem geworden, was ich bekämpfen wollte?", sourceObjectiveStatus = "unverified-source-field" }
quests[85390] = { id = 85390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgensonnenschäumer" }
quests[85394] = { id = 85394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Auge für Ärger", description = "Ein möglicher Silberstreif ist, dass wir jetzt zumindest wissen, dass unser Gebräu funktioniert. Nur nicht bei denen, für die wir es hergestellt haben.\n\nIst es zu viel verlangt, Euch darum zu bitten, diese ermächtigte Version der Kreatur zu besiegen? Es stehen schließlich nur Euer Ruf und die Zukunft von Tazavesh auf dem Spiel.\n\nDas ist eine weitere Chance, zu beweisen, dass Ihr so mächtig seid wie von allen behauptet wird.", sourceObjective = "Besiegt Bakishroth den Ermächtigten und rettet Tazavesh!", progress = "Ist es erledigt, {name}?", completion = "Es ist nicht alles verloren. Mit der Zeit wird dieser Vorfall in Vergessenheit geraten, und ich weiß, dass das Getränk funktionieren kann.\n\nNächstes Mal werde ich alles richtig machen, und wir werden gewappnet sein, falls noch so eine \"wohlwollende\" Gruppe wie das Geflecht Unheil über uns bringen wird.\n\nIch werde mich vermutlich eine Weile lang bedeckt halten müssen, aber Ihr, {name}... Ihr seid ein Held! Und Helden verdienen Belohnungen. Lasst mich nachsehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[85396] = { id = 85396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrotthaufen" }
quests[85397] = { id = 85397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Pflanzen wollen" }
