quests[85402] = { id = 85402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Höhen" }
quests[85409] = { id = 85409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer petzt, wird verletzt", description = "Ich dachte, hier in Gossenheim könnten wir uns ungestört unterhalten, aber es liegt etwas in der Luft. Die gehören alle zur Venture Company, aber ich erkenne nur wenige. Es heißt, Gallywix hätte einen Haufen loyaler Arbeiter hierhergeschickt, damit sie uns ausspionieren können.\n\nKümmert Euch um diese Verräter. Wenn nur einer von denen Aufseher Gozzic steckt, dass wir gegen die Rohrleitung arbeiten, sind wir dran.", sourceObjective = "Beseitigt die spionierenden Verräter der Venture Company in Gossenheim.", progress = "Die Spione sind überall, ich sag's Euch.", completion = "Da waren mehr Spione, als ich erwartet hatte. Es fällt schwer, Venture Company noch zu trauen. Aber wir sind nicht alle so.", sourceObjectiveStatus = "unverified-source-field" }
quests[85410] = { id = 85410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lorenhalls langer Schatten", description = "Diese Ingenieure haben viel durchgemacht. Stellen wir sicher, dass sie wohlauf sind. Vielleicht können sie etwas Licht ins Dunkel bringen, was Lorenhall angeht.", sourceObjective = "Sprecht mit Pamsys Ingenieuren.", completion = "Unser nächster Halt sollte Lorenhall sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[85427] = { id = 85427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosives Ende" }
quests[85428] = { id = 85428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodexverstöße" }
quests[85429] = { id = 85429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigt sie", description = "Es steht eine Prüfung an. Mein Arbeitgeber, Xy Importe, wird erneut geprüft. Wieder einmal.\n\n<Xy'nell zittert sichtbar und senkt den Kopf.>\n\nDiese Prüfung muss richtig schiefgehen. Sie muss schlimmer laufen als die letzte.\n\nKönnt Ihr mir helfen? Wir haben eine Ladung kleiner Verschlinger, die eine Menge Ärger verursachen würden, wenn sie entkommen oder verschwinden würden.\n\nBrecht ihre Kisten auf. Das Geschäft muss genauso überfordert sein wie beim letzten Mal.", sourceObjective = "Brecht 8 Kisten von Xy Importe auf den Docks in Tazavesh auf.", completion = "Gut. Gut. Die Dinge geraten aus den Fugen. Das ist ein Anfang.\n\nVielleicht seid Ihr genau das Maß an Chaos, das ich brauchte, um es zu schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85430] = { id = 85430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflichturlaub", description = "Wenn meine Kollegen von meinem Plan wüssten, würden sie Gefahr laufen, ihre Eide als gute Angestellte zu brechen. Abgesehen davon sind sie viel zu gut in dem, was sie tun.\n\nHier. Diese Geräte habe ich persönlich erfunden. Werden sie in der Nähe meiner Kollegen platziert, erzeugen sie die Illusion, dass sie arbeiten.\n\nSo können sie sich zurückziehen und ausruhen. Und das Geschäft wird ohne sie noch mehr unter Druck geraten.", sourceObjective = "Platziert 7 Illusionsgeräte.", completion = "Ich bin froh, dass keiner meiner Kollegen mitansehen muss, was wir hier tun. Sie haben sich die Pause verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[85431] = { id = 85431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzieht ihnen ihre Ressourcen", description = "Wir haben gute Fortschritte gemacht, aber wir brauchen mehr Chaos.\n\nIch habe eine besonders große Ladung Anima in Form eines Verschlingers umgeleitet. Tötet ihn und bringt mir den Animakern.\n\nDie Anima selbst ist nicht wichtig. Vielmehr die Tatsache, dass sie gestohlen werden kann. Mein Boss wird bei der Prüfung mehr zu erklären haben, wenn seine Buchhaltung nicht in Ordnung ist.", sourceObjective = "Sammelt den überfließenden Animakern von Respleth dem Hungernden vor den Toren von Tazavesh.", progress = "Die Mitarbeiter von Importe Xy, die diese Anima transportieren, erwarten einen... nun ja, eine Art Mittler, dem sie ihre Ladung übergeben können.\n\nSie werden Euch keine Probleme bereiten.", completion = "Danke, {name}.\n\n\n\nNoch mehr belastende Beweise für die Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[85432] = { id = 85432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwirrt ihre Kontakte", description = "Wenn unsere Importe verzögert werden oder verloren gehen, trifft das die Unternehmen in Tazavesh am härtesten.\n\nNehmt diese Illusionsanstecknadel. Sie tarnt Euch als einen Angestellten von Xy Importe. Sagt den Unternehmen, ihre Sendungen seien auf unbestimmte Zeit verzögert.\n\nMein Boss kann den Druck auf die weitere Lieferkette nicht ewig ignorieren.", sourceObjective = "Sprecht mit Verkäufern auf dem Markt von Tazavesh.", completion = "<Xy'nells Stimme klingt heiser.>\n\nWir werden ihre Sorgen bald aus der Welt schaffen. Besser eine vorübergehende Belastung als ewiger, dauernder Stress.", sourceObjectiveStatus = "unverified-source-field" }
quests[85433] = { id = 85433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Augen auf uns", description = "Ich kann bereits hören, wie Koordinator Xy'thir sich über den Rückgang an Geschäften beschwert.\n\n<Xy'nell ist unruhig und duckt seinen Kopf.>\n\nWir sind bereit. Begebt Euch zum Hafenbeamten Zo'rau. Sagt, dass Ihr eine involvierte Partei vertretet und die Prüfung vorverlegt werden soll.\n\nUnd es gibt noch etwas, das Ihr für mich tun müsst. Sprecht mit mir, bevor Ihr geht.", sourceObjective = "Sprecht mit dem Hafenbeamten Zo'rau in Tazavesh.", progress = "Das ist wichtiger, als ich in Worte fassen kann, {name}. Doch ich kann meinen Schwur nicht brechen. Bringt die Anstecknadel zu Zo'rau.", completion = "Zo'rau trägt die Anstecknadel.\n\n<Xy'nells Schultern entspannen sich.>\n\nDanke, {name}. Jetzt müssen wir vorsichtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[85434] = { id = 85434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfahrensfehler", sourceObjective = "Konfrontiert Koordinator Xy'thir in Tazavesh.", progress = "<Xy'nell bleibt vor Koordinator Xy'thir stumm.>", completion = "Danke, {name}. Danke für alles.\n\n\n\nJetzt machen wir uns an die Arbeit, das Geschäft wieder auf die richtige Spur zu bringen. Aber vielleicht nach einer kleinen Verschnaufpause.\n\nIch... Ich kann mich ausruhen! Der Koordinator... er kann mich nicht mehr finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[85438] = { id = 85438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonst setzt's was!", description = "Bin ich froh, Euch gefunden zu haben, {name}!\n\nIch komme im Auftrag meines Bosses, Kraz Drillzang, der kein Nein akzeptiert, alles klar? Ich dachte schon, ich müsste alles verscherbeln und mich tiefer in den Untergrund zurückziehen, aber da kommt Ihr!\n\nJedenfalls heiratet die Tochter des Bosses und er meinte, er bräuchte ausdrücklich Eure Hilfe, um ein paar \"Details\" mit ihrem Liebsten und den Gästen zu regeln, wenn Ihr versteht, was ich meine.", sourceObjective = "Sprecht mit Kraz Drillzang in Bruchbudenhügel.", completion = "Ich brauche jemanden mit Elan, der seinen Job schnell und geräuschlos erledigt und mir hilft, alle für den großen Tag meiner Kleinen vorzubereiten. Und das seid Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[85444] = { id = 85444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefundene Familie", description = "Der Trupp hat mir vertraut. Wir sind wie eine Familie. Wir müssen nachsehen, ob irgendjemand überlebt hat.\n\nIch hab andere Ingenieure, die nicht hier sind. Sie sind vermutlich ins Feld geflohen. Razi, Keets und Glizza sind da draußen. Findet sie. Bringt sie heim.", sourceObjective = "Rettet Pamsys letzte Ingenieure aus den Zuckenden Feldern.", progress = "Ihr dürft die Ingenieure da draußen nicht sterben lassen.", completion = "Wir haben einige Fortschritte gemacht, während Ihr Pamsys Ingenieuren geholfen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85449] = { id = 85449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phasenverschiebung", description = "Sobald der Angriff der Astralen begann, hat die Phasenresonanz Risse im Gebiet entstehen lassen. Die Risse sind verschwunden, aber die Astralen können zurückkehren, solange die Resonanz bestehen bleibt. Auf diese Weise rufen sie mehr Soldaten und kommunizieren mit ihren Befehlshabern.\n\nWir müssen diese Resonanz zerstören.\n\nDamit ziehen wir vermutlich den Zorn des Urhebers dieser Attacke auf uns, aber ich lade ihn gern ein, herzukommen, um uns aufzuhalten zu versuchen.", sourceObjective = "Zerstört 4 Phasenresonanzen in den Bottichwerken.", progress = "Wir müssen diese Resonanz zerstören, wenn wir den Angriff aufhalten wollen.", completion = "Das Dunkle Herz war die ganze Zeit in Lorenhall. Ich hätte es wissen müssen.\n\nWenn die Astralen das Dunkle Herz vor uns erreichen, ist alles verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[85450] = { id = 85450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierungsplan", description = "Wir dürfen nicht zulassen, dass die Astralen das Dunkle Herz vor uns finden.\n\nGazlowe muss davon erfahren. Wir müssen unsere Kräfte versammeln und das Dunkle Herz aufspüren - schnell!", sourceObjective = "Versammelt Euch mit Gazlowe in den Dampfdrucklaboren.", progress = "Wir müssen dieser Sache auf den Grund gehen.", completion = "Wenn Gallywix das Dunkle Herz in seinem Lagerhaus hat, dann müssen wir in dieses Lagerhaus kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85451] = { id = 85451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Brand von Hammerfall", description = "Das Syndikat hat Hammerfall in Brand gesetzt!\n\nDie Feiglinge setzen Pyromanten ein, um die Flammen zu nähren!\n\nAber wir können unsere Hütten noch retten, wenn wir rasch handeln.\n\nKämpft Euch durch die Banditen des Syndikats zu einem der Gebäude durch und blast dieses Horn. Ein Schamane aus Hammerfall wird kommen und die Flammen löschen!", sourceObjective = "Benutzt das Horn von Hammerfall an jedem Hauptgebäude in Hammerfall, um einen Schamanen zu rufen und das Feuer zu löschen.", completion = "Hah! So stark wie Orcs!\n\nSo wie wir!", sourceObjectiveStatus = "unverified-source-field" }
quests[85459] = { id = 85459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Animarücknahmeprogramm", description = "Die Biokuppeln werden mit Anima betrieben. Wenn Ihr draußen in K'aresh unterwegs seid und auf Verschlinger trefft, tötet sie und bringt ihre Anima zurück.\n\nIhr werdet dafür entlohnt.", sourceObjective = "Sammelt 20 Verschlingeranima in K'aresh.", progress = "Unsere Reserven befinden sich nicht in unmittelbarer Gefahr, aber sicher ist sicher, nicht wahr?", completion = "Ausgezeichnet! Jetzt müsstet Ihr etwas Stygia für mich sammeln.\n\nIst ein Witz, {name}. Ich kann auch Witze machen. Gelegentlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[85460] = { id = 85460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ökologische Erhaltung" }
quests[85461] = { id = 85461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahrung auf Abwegen", description = "Die letzte Nahrungslieferung für unsere Tiere ist bei einem Überfall in Tazavesh von Astralen gestohlen worden.\n\nIch möchte, dass Ihr sie zurückbringt.", sourceObjective = "Bergt 15 gestohlene Nahrungslieferungen von Astralen in Tazavesh.", progress = "Konntet Ihr die Nahrung zurückbringen?", completion = "Eure Kapazität für Gewalt erfreut mich immer wieder aufs Neue, {name}.\n\nDie Astrale werden das sicher anders sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[85462] = { id = 85462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Herausforderung der Dominanz", description = "Unser Schieferrückenalpha ist in letzter Zeit etwas... gereizt. Ich glaube, er sucht nach einer Herausforderung. \n\nIhr habt die meiste Kampferfahrung von uns. Geht und stellt Euch ihm.", sourceObjective = "Fordert den Schieferrückenalpha heraus.", completion = "Was für ein spektakulärer Kampf, wie gewohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[85465] = { id = 85465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ball spielen", description = "Dieses Dornschweifjunge bettelt schon den ganzen Morgen um Aufmerksamkeit. Es ist wirklich bezaubernd, aber ich habe zu tun!\n\nIch glaube, es muss sich etwas verausgaben. Nehmt diesen Ball und spielt mit ihm.", sourceObjective = "Fangt einen Ball 10-mal, während Ihr mit Eurem Dornschweifjungen spielt.", progress = "<Om'talad streichelt das Dornschweifjunge geistesabwesend.>", completion = "Endlich kriege ich etwas Arbeit erledigt.\n\n<Einer von Om'talads vier Armen krault das Dornschweifjunge hinter den Ohren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[85466] = { id = 85466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herd und kalt" }
