quests[85470] = { id = 85470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzelbehandlung", description = "Einige der Schoßkäfer haben sich wieder in den Baumwurzeln verfangen. Sie würden sich irgendwann selbst befreien, aber mit Eurer Unterstützung ginge es gewiss einfacher.", sourceObjective = "Befreit 10 feststeckende Schoßkäfer.", completion = "Vielen Dank. Ich hoffe, dass sie jetzt nicht mehr stecken bleiben, aber wir wissen wohl beide, dass das nicht das letzte Mal war.", sourceObjectiveStatus = "unverified-source-field" }
quests[85471] = { id = 85471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen im Garbagio Treueclub", description = "Das Garbagio weiß Eure anhaltende Loyalität zu schätzen!\n\nWir haben einige Extravorräte für unsere verehrtesten Glücksroller zurückgelegt. Besucht uns für Euer Geschenk!", sourceObjective = "Sprecht mit Paula Piranha in der Befreiung von Lorenhall.", completion = "Bitte sehr!", sourceObjectiveStatus = "unverified-source-field" }
